// The Westminster Confession of Faith (1646), chapter by chapter. Chapter 23 follows the American revision (1788); 20.4 and 31 note where that revision differs.
// The English text is in the public domain; the Arabic here is our own paraphrase
// in simple language, section by section, with a selection of the Assembly's proof texts.
// `id` is the topic page that treats the chapter in depth.
export default [
  { n: 1, ar: 'الكتاب المقدس', en: 'Of the Holy Scripture', id: 'scripture', secs: [
    { t: 'نور الطبيعة وأعمال الخليقة والعناية تكشف صلاح الله وحكمته وقدرته إلى حد يجعل الإنسان بلا عذر، لكنها لا تكفي لتعطي معرفة الله ومشيئته اللازمة للخلاص. لذلك تكلم الله بطرق كثيرة، ثم شاء أن يدوّن هذا الإعلان كله كتابة، فصار الكتاب المقدس ضرورياً جداً، بعد أن توقفت تلك الطرق القديمة.', refs: ['Rom.1.19-20', 'Ps.19.1-3', 'Heb.1.1-2', '2Tim.3.15'] },
    { t: 'الكتاب المقدس، أي كلمة الله المكتوبة، يضم أسفار العهدين القديم والجديد التي أوحى بها الله لتكون قانون الإيمان والحياة.', refs: ['Eph.2.20', 'Rev.22.18-19', '2Tim.3.16'] },
    { t: 'الأسفار المعروفة بالأبوكريفا ليست موحى بها، فليست جزءاً من قانون الكتاب، ولا سلطان لها في الكنيسة، ويجوز قراءتها ككتابات بشرية فقط.', refs: ['Luke.24.27', 'Luke.24.44', 'Rom.3.2'] },
    { t: 'سلطان الكتاب الذي يوجب علينا تصديقه وطاعته لا يأتي من شهادة إنسان أو كنيسة، بل من الله نفسه، كاتبه، وهو الحق ذاته. لذلك نقبله لأنه كلمة الله.', refs: ['2Pet.1.19-21', '1Thess.2.13', '1John.5.9'] },
    { t: 'قد تقودنا شهادة الكنيسة إلى تقدير عالٍ للكتاب، وفيه علامات كثيرة تشهد أنه كلمة الله: سمو موضوعه، وفاعلية تعليمه، وتناغم أجزائه، وغايته أن يعطي المجد كله لله. لكن اقتناعنا الكامل بحقه وسلطانه يأتي من عمل الروح القدس الداخلي الذي يشهد بالكلمة ومعها في قلوبنا.', refs: ['1Tim.3.15', '1John.2.20', '1John.2.27', 'John.16.13-14', '1Cor.2.10-12'] },
    { t: 'مشورة الله الكاملة في كل ما يلزم لمجده ولخلاص الإنسان وإيمانه وحياته مكتوبة صراحة في الكتاب، أو تُستنتج منه بنتيجة صحيحة ولازمة. ولا يُضاف إليه شيء في أي وقت، لا بإعلانات جديدة من الروح ولا بتقاليد البشر. ومع ذلك نحتاج إلى استنارة الروح الداخلية لفهم الكلمة فهماً مخلّصاً، وبعض أمور العبادة وتنظيم الكنيسة تُرتب بنور الطبيعة والحكمة المسيحية في إطار القواعد العامة للكلمة.', refs: ['2Tim.3.15-17', 'Gal.1.8-9', 'John.6.45', '1Cor.2.9-12', '1Cor.14.26', '1Cor.14.40'] },
    { t: 'ليست كل أجزاء الكتاب واضحة بنفس الدرجة، ولا واضحة للجميع بالقدر نفسه. لكن ما يلزم معرفته والإيمان به وحفظه للخلاص معلن بوضوح في موضع أو آخر، بحيث يستطيع المتعلم وغير المتعلم أن يصل إلى فهم كافٍ له باستخدام الوسائل العادية.', refs: ['2Pet.3.16', 'Ps.119.105', 'Ps.119.130'] },
    { t: 'العهد القديم بالعبرية والجديد باليونانية هما النص الموحى به مباشرة من الله، والمحفوظ بعنايته عبر العصور، ولذلك هما المرجع الأخير في كل خلاف ديني. ولأن شعب الله كله له حق في الكتاب، يجب أن يُترجم إلى لغة كل أمة، حتى تسكن كلمة الله فيهم بغنى ويعبدوه كما يليق.', refs: ['Matt.5.18', 'Isa.8.20', 'John.5.39', '1Cor.14.6', '1Cor.14.9', 'Col.3.16'] },
    { t: 'القاعدة المعصومة لتفسير الكتاب هي الكتاب نفسه. فحين يختلف فهم نص ما، نبحث عنه ونفهمه بمواضع أخرى أوضح.', refs: ['2Pet.1.20-21', 'Acts.15.15-16'] },
    { t: 'القاضي الأعلى الذي تُحسم به كل الخلافات الدينية، وتُفحص به قرارات المجامع وآراء الكتّاب القدماء وتعاليم البشر، هو الروح القدس متكلماً في الكتاب، وحكمه هو الذي نستريح إليه.', refs: ['Matt.22.29', 'Matt.22.31', 'Acts.28.25', 'Eph.2.20'] }
  ] },
  { n: 2, ar: 'الله والثالوث القدوس', en: 'Of God, and of the Holy Trinity', id: 'god', secs: [
    { t: 'يوجد إله واحد فقط، حي وحقيقي، غير محدود في كيانه وكماله، روح نقي جداً، غير منظور، بلا جسد ولا أعضاء ولا انفعالات، لا يتغير، غير محدود بمكان، أزلي، لا يُدرك كماله، قادر على كل شيء، حكيم جداً، قدوس جداً، حر تماماً، مطلق، يعمل كل شيء حسب مشورة مشيئته الثابتة البارة لمجده. وهو محب جداً، كثير النعمة، رحيم، طويل الأناة، كثير الصلاح والحق، يغفر الإثم والمعصية والخطية، ويكافئ الذين يطلبونه. وهو أيضاً عادل جداً ومخوف في أحكامه، يبغض كل خطية، ولا يبرئ المذنب.', refs: ['Deut.6.4', '1Cor.8.4-6', 'John.4.24', '1Tim.1.17', 'Mal.3.6', 'Isa.6.3', 'Eph.1.11', 'Exod.34.6-7', 'Heb.11.6', 'Neh.9.32-33'] },
    { t: 'لله في ذاته ومن ذاته كل حياة ومجد وصلاح وبركة. هو كافٍ لذاته تماماً، لا يحتاج إلى أي مخلوق صنعه، ولا يأخذ منه مجداً، بل يُظهر مجده فيهم وبهم. هو مصدر كل كيان، ومنه وبه وله كل الأشياء، وله السلطان المطلق عليها. كل شيء مكشوف أمامه، ومعرفته غير محدودة ومعصومة، فلا شيء عنده عارض أو غير مؤكد. وله تحق كل عبادة وخدمة وطاعة من الملائكة والبشر وكل خليقة.', refs: ['John.5.26', 'Acts.17.24-25', 'Rom.11.36', 'Rev.4.11', 'Heb.4.13', 'Rom.11.33-34', 'Rev.5.12-14'] },
    { t: 'في وحدانية اللاهوت ثلاثة أقانيم، من جوهر واحد وقدرة واحدة وأزلية واحدة: الله الآب، والله الابن، والله الروح القدس. الآب ليس من أحد، لا مولود ولا منبثق. والابن مولود من الآب أزلياً. والروح القدس منبثق أزلياً من الآب والابن.', refs: ['Matt.3.16-17', 'Matt.28.19', '2Cor.13.14', 'John.1.14', 'John.1.18', 'John.15.26', 'Gal.4.6'] }
  ] },
  { n: 3, ar: 'القضاء الأزلي لله', en: "Of God's Eternal Decree", id: 'election', secs: [
    { t: 'قضى الله منذ الأزل، بمشورة مشيئته الحكيمة والمقدسة جداً، بحرية ودون تغيير، كل ما يحدث. لكنه ليس صانع الخطية، ولا تُلغى إرادة المخلوقات، ولا تُنزع حرية الأسباب الثانوية أو عَرَضيتها، بل تُثبَّت.', refs: ['Eph.1.11', 'Rom.11.33', 'Heb.6.17', 'Jas.1.13', 'Acts.2.23', 'Acts.4.27-28'] },
    { t: 'مع أن الله يعرف كل ما يمكن أن يحدث في كل الظروف، لم يقضِ بشيء لأنه رآه مسبقاً سيحدث، بل قضاؤه سابق ومستقل.', refs: ['Acts.15.18', 'Rom.9.11', 'Rom.9.13', 'Rom.9.16'] },
    { t: 'بقضاء الله، ولإظهار مجده، سبق فعيّن بعض البشر والملائكة للحياة الأبدية، وسبق فعيّن آخرين للموت الأبدي.', refs: ['1Tim.5.21', 'Matt.25.41', 'Rom.9.22-23', 'Eph.1.5-6'] },
    { t: 'هؤلاء المعيّنون محددون بأشخاصهم وبعددهم تحديداً لا يتغير، فلا يُزاد عليه ولا يُنقص منه.', refs: ['2Tim.2.19', 'John.13.18'] },
    { t: 'الذين اختارهم الله للحياة، اختارهم في المسيح قبل تأسيس العالم، حسب قصده الأزلي ومسرة مشيئته، للمجد الأبدي، بمحض نعمته ومحبته المجانية، لا لأنه رأى فيهم مسبقاً إيماناً أو أعمالاً صالحة أو ثباتاً أو أي شيء آخر كشرط أو سبب، وكل ذلك لمدح نعمته المجيدة.', refs: ['Eph.1.4', 'Eph.1.9', 'Eph.1.11', 'Rom.8.30', '2Tim.1.9', '1Thess.5.9', 'Rom.9.11', 'Eph.2.8-9'] },
    { t: 'وكما عيّن المختارين للمجد، عيّن أيضاً كل الوسائل المؤدية إليه: فالمختارون الساقطون في آدم يُفتدون بالمسيح، ويُدعون دعوة فعالة إلى الإيمان به بروحه، ويُبررون ويُتبنون ويُقدسون ويُحفظون بقدرته بالإيمان للخلاص. ولا يُفتدى ولا يُدعى دعوة فعالة ولا يُبرر ولا يُتبنى ولا يُقدس ولا يخلص إلا المختارون وحدهم.', refs: ['1Pet.1.2', 'Eph.1.4-5', '2Thess.2.13', '1Pet.1.5', 'John.17.9', 'Rom.8.28-39', 'John.6.64-65', 'John.10.26'] },
    { t: 'أما باقي البشر فقد سُر الله، حسب مشورة مشيئته التي لا تُستقصى، والتي بها يمنح الرحمة أو يمسكها كما يشاء، لمجد سلطانه على خلائقه، أن يتجاوزهم، ويعيّنهم للعار والغضب بسبب خطيتهم، لمدح عدله المجيد.', refs: ['Matt.11.25-26', 'Rom.9.17-18', 'Rom.9.21-22', '2Tim.2.19-20', 'Jude.1.4', '1Pet.2.8'] },
    { t: 'هذا التعليم السامي يجب أن يُعالج بحكمة وحرص خاصين، حتى يتيقن الناس الذين يصغون إلى مشيئة الله المعلنة في كلمته ويطيعونها، من خلال يقين دعوتهم الفعالة، أنهم مختارون. وبهذا يصير التعليم سبب تسبيح وتوقير وإعجاب بالله، وسبب تواضع واجتهاد وتعزية وافرة لكل من يطيع الإنجيل بإخلاص.', refs: ['Rom.9.20', 'Rom.11.33', 'Deut.29.29', '2Pet.1.10', 'Eph.1.6', 'Rom.11.5-6', 'Luke.10.20'] }
  ] },
  { n: 4, ar: 'الخلق', en: 'Of Creation', id: 'creation', secs: [
    { t: 'سُر الله الآب والابن والروح القدس، لإظهار مجد قدرته الأزلية وحكمته وصلاحه، أن يخلق من العدم في البدء العالم وكل ما فيه، المنظور وغير المنظور، في مدة ستة أيام، وكان كله حسناً جداً.', refs: ['Heb.1.2', 'John.1.2-3', 'Gen.1.2', 'Job.26.13', 'Rom.1.20', 'Jer.10.12', 'Gen.1.1-31', 'Heb.11.3', 'Col.1.16', 'Exod.20.11'] },
    { t: 'بعد أن خلق الله كل المخلوقات الأخرى، خلق الإنسان ذكراً وأنثى، بنفوس عاقلة خالدة، ووهبهم المعرفة والبر والقداسة الحقيقية على صورته، وكتب ناموسه في قلوبهم، وأعطاهم القدرة على تتميمه. لكنهم كانوا قابلين أن يتعدوه، إذ تُركوا لحرية إرادتهم القابلة للتغير. وإلى جانب هذا الناموس المكتوب في القلب، أُعطوا وصية ألا يأكلوا من شجرة معرفة الخير والشر. وما داموا حفظوها كانوا سعداء في شركة مع الله، ومتسلطين على المخلوقات.', refs: ['Gen.1.27', 'Gen.2.7', 'Eccl.12.7', 'Eph.4.24', 'Col.3.10', 'Rom.2.14-15', 'Eccl.7.29', 'Gen.3.6', 'Gen.2.17', 'Gen.1.26', 'Gen.1.28'] }
  ] },
  { n: 5, ar: 'العناية الإلهية', en: 'Of Providence', id: 'providence', secs: [
    { t: 'الله، خالق كل شيء، يسند ويوجه ويدبّر ويحكم كل المخلوقات والأعمال والأشياء، من الأعظم إلى الأصغر، بعنايته الحكيمة والمقدسة جداً، حسب علمه السابق المعصوم ومشورة مشيئته الحرة الثابتة، لمدح مجد حكمته وقدرته وعدله وصلاحه ورحمته.', refs: ['Heb.1.3', 'Dan.4.34-35', 'Ps.135.6', 'Acts.17.25-28', 'Matt.10.29-31', 'Prov.15.3', 'Eph.1.11', 'Isa.63.14'] },
    { t: 'مع أن كل شيء يحدث بثبات ودون خطأ بالنسبة لعلم الله السابق وقضائه، السبب الأول، فإنه بنفس العناية يرتب الأشياء لتحدث حسب طبيعة الأسباب الثانوية: بالضرورة، أو بحرية، أو عَرَضاً.', refs: ['Acts.2.23', 'Gen.8.22', 'Jer.31.35', 'Exod.21.13', 'Deut.19.5', '1Kgs.22.28', '1Kgs.22.34', 'Isa.10.6-7'] },
    { t: 'الله في عنايته العادية يستخدم الوسائل، لكنه حر أن يعمل بدونها، أو فوقها، أو ضدها، كما يشاء.', refs: ['Acts.27.31', 'Acts.27.44', 'Isa.55.10-11', 'Hos.1.7', 'Rom.4.19-21', '2Kgs.6.6', 'Dan.3.27'] },
    { t: 'قدرة الله وحكمته وصلاحه تظهر في عنايته إلى حد أنها تمتد حتى إلى السقطة الأولى وكل خطايا الملائكة والبشر، لا بمجرد سماح، بل بضبطها وتحديدها وترتيبها وتوجيهها بحكمة وقوة لغاياته المقدسة. ومع ذلك فالخطية تصدر من المخلوق وحده، لا من الله، القدوس البار، الذي ليس صانع الخطية ولا يوافق عليها.', refs: ['Rom.11.32-34', '2Sam.24.1', '1Chr.21.1', '1Kgs.22.22-23', 'Acts.4.27-28', 'Gen.50.20', 'Isa.10.6-7', 'Isa.10.12', 'Jas.1.13-14', '1John.2.16'] },
    { t: 'الله الحكيم البار الكريم كثيراً ما يترك أولاده لبعض الوقت لتجارب متنوعة ولفساد قلوبهم، ليؤدبهم على خطايا سابقة، أو ليكشف لهم قوة فساد قلوبهم وخداعها حتى يتواضعوا، وليقودهم إلى اتكال أقرب وأدوم عليه، وليجعلهم أكثر سهراً ضد الخطية، ولغايات عادلة ومقدسة أخرى.', refs: ['2Chr.32.25-26', '2Chr.32.31', '2Sam.24.1', '2Cor.12.7-9', 'Ps.73.1-28', 'Ps.77.1-12', 'Mark.14.66-72', 'John.21.15-17'] },
    { t: 'أما الأشرار الذين يقسيهم الله كديّان بار بسبب خطاياهم السابقة، فهو لا يمسك عنهم نعمته التي كانت تنير أذهانهم وتلين قلوبهم فحسب، بل أحياناً يسحب ما كان لديهم من عطايا، ويعرّضهم لظروف يحولها فسادهم إلى فرص للخطية، ويسلمهم لشهواتهم وتجارب العالم وقوة الشيطان، فيقسّون أنفسهم حتى بالوسائل نفسها التي يلين بها الله آخرين.', refs: ['Rom.1.24', 'Rom.1.26', 'Rom.1.28', 'Rom.11.7-8', 'Deut.29.4', 'Matt.13.12', 'Matt.25.29', '2Kgs.8.12-13', 'Ps.81.11-12', '2Thess.2.10-12', 'Exod.7.3', 'Exod.8.15', 'Exod.8.32', '2Cor.2.15-16', 'Isa.6.9-10'] },
    { t: 'وكما تصل عناية الله إلى كل المخلوقات بوجه عام، كذلك تعتني بطريقة خاصة جداً بكنيسته، وتدبّر كل الأشياء لخيرها.', refs: ['1Tim.4.10', 'Amos.9.8-9', 'Rom.8.28', 'Isa.43.3-5', 'Isa.43.14'] }
  ] },
  { n: 6, ar: 'سقوط الإنسان والخطية وقصاصها', en: 'Of the Fall of Man, of Sin, and of the Punishment Thereof', id: 'fall', secs: [
    { t: 'أبوانا الأولان، إذ أغواهما الشيطان بمكره، أخطآ بالأكل من الثمرة المحرمة. وقد سُر الله، حسب مشورته الحكيمة المقدسة، أن يسمح بخطيتهما، إذ قصد أن يرتبها لمجده.', refs: ['Gen.3.13', '2Cor.11.3', 'Rom.11.32'] },
    { t: 'بهذه الخطية سقطا من برهما الأصلي ومن شركتهما مع الله، فصارا أمواتاً في الخطية، وتنجّسا كلياً في كل قوى النفس وأعضاء الجسد.', refs: ['Gen.3.6-8', 'Eccl.7.29', 'Rom.3.23', 'Gen.2.17', 'Eph.2.1', 'Titus.1.15', 'Gen.6.5', 'Jer.17.9', 'Rom.3.10-18'] },
    { t: 'ولأنهما أصل كل الجنس البشري، حُسب ذنب هذه الخطية على كل نسلهما، وانتقل إليهم الموت نفسه في الخطية والطبيعة الفاسدة، إذ يتناسلون منهما بالولادة الطبيعية.', refs: ['Gen.1.27-28', 'Gen.2.16-17', 'Acts.17.26', 'Rom.5.12', 'Rom.5.15-19', '1Cor.15.21-22', '1Cor.15.45', '1Cor.15.49', 'Ps.51.5', 'Gen.5.3', 'Job.14.4'] },
    { t: 'من هذا الفساد الأصلي، الذي به صرنا عاجزين تماماً وغير راغبين ومعادين لكل صلاح، ومائلين كلياً إلى كل شر، تخرج كل الخطايا الفعلية.', refs: ['Rom.5.6', 'Rom.8.7', 'Rom.7.18', 'Col.1.21', 'Gen.6.5', 'Gen.8.21', 'Rom.3.10-12', 'Jas.1.14-15', 'Eph.2.2-3', 'Matt.15.19'] },
    { t: 'هذا الفساد الطبيعي يبقى في المولودين ثانية طوال هذه الحياة. ومع أنه مغفور ومُمات بالمسيح، فهو نفسه وكل حركاته خطية حقاً وفعلاً.', refs: ['1John.1.8', '1John.1.10', 'Rom.7.14', 'Rom.7.17-18', 'Rom.7.23', 'Jas.3.2', 'Prov.20.9', 'Eccl.7.20', 'Rom.7.5', 'Rom.7.7-8', 'Rom.7.25', 'Gal.5.17'] },
    { t: 'كل خطية، أصلية كانت أو فعلية، هي تعدٍّ على ناموس الله البار ومخالفة له، فتجلب بطبيعتها الذنب على الخاطئ، فيصير تحت غضب الله ولعنة الناموس، ومعرَّضاً للموت بكل بؤسه الروحي والجسدي والأبدي.', refs: ['1John.3.4', 'Rom.2.15', 'Rom.3.9', 'Rom.3.19', 'Eph.2.3', 'Gal.3.10', 'Rom.6.23', 'Eph.4.18', 'Rom.8.20', 'Lam.3.39', 'Matt.25.41', '2Thess.1.9'] }
  ] },
  { n: 7, ar: 'عهد الله مع الإنسان', en: "Of God's Covenant with Man", id: 'covenant', secs: [
    { t: 'المسافة بين الله والمخلوق عظيمة جداً، حتى إن المخلوقات العاقلة، مع أنها مطالبة بطاعته كخالقها، لا يمكن أن تنال منه أي ثمرة بركة أو مكافأة إلا بتنازل اختياري من جانب الله، وقد شاء أن يعبّر عنه بطريق العهد.', refs: ['Isa.40.13-17', 'Job.9.32-33', 'Ps.113.5-6', 'Ps.100.2-3', 'Luke.17.10', 'Acts.17.24-25'] },
    { t: 'العهد الأول مع الإنسان كان عهد أعمال، وفيه وُعد آدم، وفيه نسله، بالحياة بشرط الطاعة الكاملة الشخصية.', refs: ['Gal.3.12', 'Rom.10.5', 'Rom.5.12-20', 'Gen.2.17', 'Gal.3.10'] },
    { t: 'ولأن الإنسان بسقوطه صار عاجزاً عن الحياة بهذا العهد، سُر الرب أن يقطع عهداً ثانياً يُسمى عادة عهد النعمة، وفيه يقدم مجاناً للخطاة الحياة والخلاص بيسوع المسيح، طالباً منهم الإيمان به ليخلصوا، وواعداً أن يعطي روحه القدوس لكل المعيّنين للحياة ليجعلهم راغبين وقادرين أن يؤمنوا.', refs: ['Gal.3.21', 'Rom.8.3', 'Rom.3.20-21', 'Gen.3.15', 'Isa.42.6', 'Mark.16.15-16', 'John.3.16', 'Rom.10.6', 'Rom.10.9', 'Ezek.36.26-27', 'John.6.44-45'] },
    { t: 'عهد النعمة هذا يُشار إليه كثيراً في الكتاب باسم «الوصية» أو الميراث المُوصى به، بالإشارة إلى موت يسوع المسيح الموصي، وإلى الميراث الأبدي وكل ما يخصه، الموهوب فيه.', refs: ['Heb.9.15-17', 'Heb.7.22', 'Luke.22.20', '1Cor.11.25'] },
    { t: 'هذا العهد أُدير بطريقة مختلفة في زمن الناموس عنه في زمن الإنجيل. في زمن الناموس أُدير بالمواعيد والنبوات والذبائح والختان وخروف الفصح ورموز وفرائض أخرى سُلّمت لشعب اليهود، كلها كانت تشير مسبقاً إلى المسيح الآتي. وكانت كافية وفعالة في ذلك الوقت، بعمل الروح، لتعليم المختارين وبنائهم في الإيمان بالمسيح الموعود، الذي به نالوا غفران الخطايا الكامل والخلاص الأبدي. ويُسمى هذا العهد القديم.', refs: ['2Cor.3.6-9', 'Heb.8.1-13', 'Heb.9.1-28', 'Heb.10.1', 'Rom.4.11', 'Col.2.11-12', '1Cor.5.7', '1Cor.10.1-4', 'Heb.11.13', 'John.8.56', 'Gal.3.7-9', 'Gal.3.14'] },
    { t: 'في زمن الإنجيل، حين ظهر المسيح، الجوهر، صارت الفرائض التي يُدار بها هذا العهد هي الكرازة بالكلمة، وممارسة سرّي المعمودية والعشاء الرباني. ومع أنها أقل عدداً وأبسط وأقل مظهراً خارجياً، فإنها تقدّم العهد بملء ووضوح وفاعلية روحية أعظم لكل الأمم، يهوداً وأمماً، ويُسمى العهد الجديد. فليس هناك إذن عهدا نعمة مختلفان في الجوهر، بل عهد واحد في إدارات مختلفة.', refs: ['Col.2.17', 'Matt.28.19-20', '1Cor.11.23-25', 'Heb.12.22-27', 'Jer.31.33-34', 'Matt.28.19', 'Eph.2.15-19', 'Luke.22.20', 'Gal.3.14', 'Gal.3.16', 'Acts.15.11', 'Rom.3.21-23', 'Rom.3.30', 'Ps.32.1', 'Rom.4.3', 'Rom.4.6', 'Rom.4.16-17', 'Rom.4.23-24', 'Heb.13.8'] }
  ] },
  { n: 8, ar: 'المسيح الوسيط', en: 'Of Christ the Mediator', id: 'christ-mediator', secs: [
    { t: 'سُر الله، في قصده الأزلي، أن يختار ويعيّن الرب يسوع، ابنه الوحيد، ليكون الوسيط بين الله والإنسان: النبي والكاهن والملك، رأس الكنيسة ومخلّصها، وارث كل الأشياء، وديّان العالم. وأعطاه منذ الأزل شعباً ليكون نسله، ويفتديه هو في الزمن ويدعوه ويبرره ويقدسه ويمجده.', refs: ['Isa.42.1', '1Pet.1.19-20', 'John.3.16', '1Tim.2.5', 'Acts.3.22', 'Heb.5.5-6', 'Ps.2.6', 'Luke.1.33', 'Eph.5.23', 'Heb.1.2', 'Acts.17.31', 'John.17.6', 'Ps.22.30', 'Isa.53.10', '1Tim.2.6', 'Isa.55.4-5', '1Cor.1.30'] },
    { t: 'ابن الله، الأقنوم الثاني في الثالوث، الإله الحقيقي الأزلي، المساوي للآب ومن جوهره، حين جاء ملء الزمان أخذ طبيعة الإنسان بكل خصائصها الجوهرية وضعفاتها العامة، لكن بلا خطية. حُبل به بقوة الروح القدس في بطن مريم العذراء ومن جوهرها. فاتحدت طبيعتان كاملتان متميزتان، اللاهوت والناسوت، في أقنوم واحد، اتحاداً لا انفصال فيه، دون تحول أو تركيب أو امتزاج. وهذا الأقنوم إله حق وإنسان حق، لكنه مسيح واحد، الوسيط الوحيد بين الله والإنسان.', refs: ['John.1.1', 'John.1.14', '1John.5.20', 'Phil.2.6', 'Gal.4.4', 'Heb.2.14', 'Heb.2.16-17', 'Heb.4.15', 'Luke.1.27', 'Luke.1.31', 'Luke.1.35', 'Col.2.9', 'Rom.9.5', '1Pet.3.18', '1Tim.3.16', 'Rom.1.3-4', '1Tim.2.5'] },
    { t: 'الرب يسوع، في طبيعته البشرية المتحدة باللاهوت، قُدس ومُسح بالروح القدس بلا كيل، وفيه كل كنوز الحكمة والعلم. وسُر الآب أن يحل فيه كل الملء، ليكون قدوساً بلا شر ولا دنس، ممتلئاً نعمة وحقاً، مؤهلاً تماماً لعمل الوسيط والضامن. ولم يأخذ هذه الوظيفة من نفسه، بل دُعي إليها من أبيه الذي سلّم إليه كل سلطان وكل دينونة وأمره أن يتممها.', refs: ['Ps.45.7', 'John.3.34', 'Col.2.3', 'Col.1.19', 'Heb.7.26', 'John.1.14', 'Acts.10.38', 'Heb.12.24', 'Heb.7.22', 'Heb.5.4-5', 'John.5.22', 'John.5.27', 'Matt.28.18', 'Acts.2.36'] },
    { t: 'قَبِل الرب يسوع هذه الوظيفة بكامل إرادته. ولكي يتممها وُلد تحت الناموس وأكمله تماماً، واحتمل أشد العذابات في نفسه مباشرة، وأقسى الآلام في جسده، وصُلب ومات، ودُفن وبقي تحت سلطان الموت، لكنه لم يرَ فساداً. وفي اليوم الثالث قام من الأموات بنفس الجسد الذي تألم فيه، وبه صعد إلى السماء، وهناك يجلس عن يمين أبيه يشفع، وسيعود ليدين البشر والملائكة عند انقضاء العالم.', refs: ['Ps.40.7-8', 'Heb.10.5-10', 'John.10.18', 'Phil.2.8', 'Gal.4.4', 'Matt.3.15', 'Matt.5.17', 'Matt.26.37-38', 'Luke.22.44', 'Matt.27.46', 'Matt.26.1-75', 'Matt.27.1-66', 'Phil.2.8', 'Acts.2.23-24', 'Acts.2.27', 'Acts.13.37', 'Rom.6.9', '1Cor.15.3-5', 'John.20.25', 'John.20.27', 'Mark.16.19', 'Rom.8.34', 'Heb.9.24', 'Heb.7.25', 'Rom.14.9-10', 'Acts.1.11', 'Acts.10.42', 'Matt.13.40-42', 'Jude.1.6', '2Pet.2.4'] },
    { t: 'الرب يسوع، بطاعته الكاملة وذبيحة نفسه التي قدمها لله مرة واحدة بالروح الأزلي، أوفى عدل أبيه تماماً، واشترى ليس المصالحة فقط، بل ميراثاً أبدياً في ملكوت السماوات، لكل الذين أعطاهم الآب له.', refs: ['Rom.5.19', 'Heb.9.14', 'Heb.9.16', 'Heb.10.14', 'Eph.5.2', 'Rom.3.25-26', 'Dan.9.24', 'Dan.9.26', 'Col.1.19-20', 'Eph.1.11', 'Eph.1.14', 'John.17.2', 'Heb.9.12', 'Heb.9.15'] },
    { t: 'مع أن عمل الفداء لم يتمّمه المسيح فعلياً إلا بعد تجسده، فإن قوته وفاعليته وفوائده نُقلت إلى المختارين في كل العصور منذ بداية العالم، بالمواعيد والرموز والذبائح التي أعلنته ورمزت إليه بأنه نسل المرأة الذي يسحق رأس الحية، والحمل المذبوح منذ تأسيس العالم، وهو هو أمساً واليوم وإلى الأبد.', refs: ['Gal.4.4-5', 'Gen.3.15', 'Rev.13.8', 'Heb.13.8'] },
    { t: 'المسيح في عمل الوساطة يعمل حسب الطبيعتين، وكل طبيعة تعمل ما يخصها. لكن بسبب وحدة الأقنوم، يُنسب أحياناً في الكتاب ما يخص طبيعة واحدة إلى الأقنوم المسمى باسم الطبيعة الأخرى.', refs: ['Heb.9.14', '1Pet.3.18', 'Acts.20.28', 'John.3.13', '1John.3.16'] },
    { t: 'لكل الذين اشترى لهم المسيح الفداء، يطبّقه وينقله إليهم بكل يقين وفاعلية: يشفع فيهم، ويعلن لهم أسرار الخلاص في الكلمة وبها، ويقنعهم بروحه أن يؤمنوا ويطيعوا، ويحكم قلوبهم بكلمته وروحه، وينتصر على كل أعدائهم بقدرته وحكمته الكلية، بطرق تتفق تماماً مع تدبيره العجيب الذي لا يُستقصى.', refs: ['John.6.37', 'John.6.39', 'John.10.15-16', '1John.2.1-2', 'Rom.8.34', 'John.15.13', 'John.15.15', 'Eph.1.7-9', 'John.17.6', 'John.14.16', 'Heb.12.2', '2Cor.4.13', 'Rom.8.9', 'Rom.8.14', 'Rom.15.18-19', 'John.17.17', 'Ps.110.1', '1Cor.15.25-26', 'Mal.4.2-3', 'Col.2.15'] }
  ] },
  { n: 9, ar: 'الإرادة الحرة', en: 'Of Free Will', id: 'free-will', secs: [
    { t: 'وهب الله إرادة الإنسان حرية طبيعية، فلا تُجبر، ولا تُحدَّد بأي ضرورة من الطبيعة نحو الخير أو الشر.', refs: ['Matt.17.12', 'Jas.1.14', 'Deut.30.19'] },
    { t: 'الإنسان في حالة البراءة كانت له الحرية والقدرة أن يريد ويعمل ما هو صالح ومرضي لله، لكن بطريقة قابلة للتغير، فكان يمكن أن يسقط منها.', refs: ['Eccl.7.29', 'Gen.1.26', 'Gen.2.16-17', 'Gen.3.6'] },
    { t: 'الإنسان بسقوطه في حالة الخطية فقد تماماً كل قدرة لإرادته على أي خير روحي يرافق الخلاص. فالإنسان الطبيعي، إذ هو معادٍ تماماً لهذا الخير وميت في الخطية، لا يستطيع بقوته الذاتية أن يغيّر نفسه ولا أن يهيئ نفسه لذلك.', refs: ['Rom.5.6', 'Rom.8.7', 'John.15.5', 'Rom.3.10', 'Rom.3.12', 'Eph.2.1', 'Eph.2.5', 'Col.2.13', 'John.6.44', 'John.6.65', 'Eph.2.2-5', '1Cor.2.14', 'Titus.3.3-5'] },
    { t: 'حين يرجع الله الخاطئ ويُدخله إلى حالة النعمة، يحرره من عبوديته الطبيعية للخطية، وبنعمته وحدها يجعله قادراً أن يريد ويعمل بحرية ما هو صالح روحياً. لكن بسبب الفساد الباقي فيه، لا يريد الصلاح بكمال ولا وحده، بل يريد أيضاً ما هو شر.', refs: ['Col.1.13', 'John.8.34', 'John.8.36', 'Phil.2.13', 'Rom.6.18', 'Rom.6.22', 'Gal.5.17', 'Rom.7.15', 'Rom.7.18-19', 'Rom.7.21', 'Rom.7.23'] },
    { t: 'إرادة الإنسان لا تصير حرة بكمال وثبات للخير وحده إلا في حالة المجد فقط.', refs: ['Eph.4.13', 'Heb.12.23', '1John.3.2', 'Jude.1.24'] }
  ] },
  { n: 10, ar: 'الدعوة الفعالة', en: 'Of Effectual Calling', id: 'calling', secs: [
    { t: 'كل الذين عيّنهم الله للحياة، وهم وحدهم، يُسر أن يدعوهم دعوة فعالة، في الوقت الذي عيّنه وقبله، بكلمته وروحه، من حالة الخطية والموت التي هم فيها بالطبيعة، إلى النعمة والخلاص بيسوع المسيح: فينير أذهانهم روحياً وخلاصياً ليفهموا أمور الله، وينزع قلب الحجر ويعطيهم قلب لحم، ويجدد إرادتهم، وبقدرته الكلية يحدد اتجاههم نحو الخير، ويجذبهم بفاعلية إلى يسوع المسيح. ومع ذلك يأتون بأتم حرية، إذ جعلتهم نعمته راغبين.', refs: ['Rom.8.30', 'Rom.11.7', 'Eph.1.10-11', '2Thess.2.13-14', '2Cor.3.3', '2Cor.3.6', 'Rom.8.2', 'Eph.2.1-5', '2Tim.1.9-10', 'Acts.26.18', '1Cor.2.10', '1Cor.2.12', 'Eph.1.17-18', 'Ezek.36.26', 'Ezek.11.19', 'Phil.2.13', 'Deut.30.6', 'John.6.44-45', 'Song.1.4', 'Ps.110.3'] },
    { t: 'هذه الدعوة الفعالة هي من نعمة الله الخاصة المجانية وحدها، لا من أي شيء رآه مسبقاً في الإنسان. والإنسان سلبي تماماً فيها، حتى يُحيا ويتجدد بالروح القدس، فيصير بذلك قادراً أن يستجيب لهذه الدعوة ويقبل النعمة المقدمة والموصلة فيها.', refs: ['2Tim.1.9', 'Titus.3.4-5', 'Eph.2.4-5', 'Eph.2.8-9', 'Rom.9.11', '1Cor.2.14', 'Rom.8.7', 'Eph.2.5', 'John.6.37', 'Ezek.36.27', 'John.5.25'] },
    { t: 'الأطفال المختارون الذين يموتون في طفولتهم يُجدَّدون ويخلصون بالمسيح بواسطة الروح، الذي يعمل متى وأين وكيف يشاء. وكذلك كل الأشخاص المختارين الآخرين العاجزين عن أن تُوجه إليهم الدعوة الخارجية بخدمة الكلمة.', refs: ['Luke.18.15-16', 'Acts.2.38-39', 'John.3.3', 'John.3.5', '1John.5.12', 'Rom.8.9', 'John.3.8', '1John.5.12', 'Acts.4.12'] },
    { t: 'غير المختارين، مع أنهم قد يُدعون بخدمة الكلمة، وقد يختبرون بعض العمليات العامة للروح، لا يأتون أبداً إلى المسيح حقاً، فلا يمكن أن يخلصوا. وبالأحرى لا يمكن أن يخلص الذين لا يعترفون بالدين المسيحي، مهما اجتهدوا أن يضبطوا حياتهم حسب نور الطبيعة وناموس الدين الذي يعترفون به. والقول بغير ذلك ضار جداً ويستحق الرفض.', refs: ['Matt.22.14', 'Matt.7.22', 'Matt.13.20-21', 'Heb.6.4-5', 'John.6.64-66', 'John.8.24', 'Acts.4.12', 'John.14.6', 'Eph.2.12', 'John.4.22', 'John.17.3', '2John.1.9-11', '1Cor.16.22', 'Gal.1.6-8'] }
  ] },
  { n: 11, ar: 'التبرير', en: 'Of Justification', id: 'justification', secs: [
    { t: 'الذين يدعوهم الله دعوة فعالة، يبررهم أيضاً مجاناً. لا بأن يسكب فيهم البر، بل بأن يغفر خطاياهم ويحسبهم ويقبلهم أبراراً. لا لشيء صُنع فيهم أو عملوه، بل من أجل المسيح وحده. ولا بأن يحسب لهم الإيمان نفسه أو فعل الإيمان أو أي طاعة إنجيلية أخرى براً، بل بأن يحسب لهم طاعة المسيح وإيفاءه، فيقبلونه هو وبره ويستندون إليه بالإيمان. وهذا الإيمان ليس منهم، بل عطية الله.', refs: ['Rom.8.30', 'Rom.3.24', 'Rom.4.5-8', '2Cor.5.19', '2Cor.5.21', 'Rom.3.22', 'Rom.3.24-25', 'Rom.3.27-28', 'Titus.3.5', 'Titus.3.7', 'Eph.1.7', 'Jer.23.6', '1Cor.1.30-31', 'Rom.5.17-19', 'Acts.10.44', 'Gal.2.16', 'Phil.3.9', 'Acts.13.38-39', 'Eph.2.7-8'] },
    { t: 'الإيمان، الذي يقبل المسيح وبره ويستند إليه، هو الأداة الوحيدة للتبرير. لكنه لا يكون وحده في الشخص المبرَّر، بل ترافقه دائماً كل النعم المخلّصة الأخرى. وهو ليس إيماناً ميتاً، بل يعمل بالمحبة.', refs: ['John.1.12', 'Rom.3.28', 'Rom.5.1', 'Jas.2.17', 'Jas.2.22', 'Jas.2.26', 'Gal.5.6'] },
    { t: 'المسيح بطاعته وموته أوفى تماماً دين كل المبرَّرين، وقدم لعدل أبيه إيفاءً حقيقياً كاملاً عنهم. ولأنه أُعطي من الآب لأجلهم، وقُبلت طاعته وإيفاؤه عوضاً عنهم، وكلاهما مجاناً لا لشيء فيهم، فتبريرهم من محض النعمة المجانية. وبهذا يتمجد عدل الله الصارم ونعمته الغنية معاً في تبرير الخطاة.', refs: ['Rom.5.8-10', 'Rom.5.19', '1Tim.2.5-6', 'Heb.10.10', 'Heb.10.14', 'Dan.9.24', 'Dan.9.26', 'Isa.53.4-6', 'Isa.53.10-12', 'Rom.8.32', '2Cor.5.21', 'Matt.3.17', 'Eph.5.2', 'Rom.3.24', 'Eph.1.7', 'Rom.3.26', 'Eph.2.7'] },
    { t: 'قضى الله منذ الأزل أن يبرر كل المختارين، وفي ملء الزمان مات المسيح لأجل خطاياهم وقام لأجل تبريرهم. ومع ذلك لا يتبررون حتى يطبّق الروح القدس المسيح عليهم فعلياً في الوقت المناسب.', refs: ['Gal.3.8', '1Pet.1.2', '1Pet.1.19-20', 'Rom.8.30', 'Gal.4.4', '1Tim.2.6', 'Rom.4.25', 'Col.1.21-22', 'Gal.2.16', 'Titus.3.4-7'] },
    { t: 'يستمر الله في غفران خطايا المبرَّرين. ومع أنهم لا يمكن أن يسقطوا أبداً من حالة التبرير، قد يقعون بخطاياهم تحت غضب الله الأبوي، فلا يُرد إليهم نور وجهه حتى يتواضعوا ويعترفوا بخطاياهم ويطلبوا الغفران ويجددوا إيمانهم وتوبتهم.', refs: ['Matt.6.12', '1John.1.7', '1John.1.9', '1John.2.1-2', 'Luke.22.32', 'John.10.28', 'Heb.10.14', 'Ps.89.31-33', 'Ps.51.7-12', 'Ps.32.5', 'Matt.26.75', '1Cor.11.30', '1Cor.11.32', 'Luke.1.20'] },
    { t: 'تبرير المؤمنين في زمن العهد القديم كان من جميع هذه الوجوه هو نفسه تبرير المؤمنين في العهد الجديد.', refs: ['Gal.3.9', 'Gal.3.13-14', 'Rom.4.22-24', 'Heb.13.8'] }
  ] },
  { n: 12, ar: 'التبني', en: 'Of Adoption', id: 'adoption', secs: [
    { t: 'كل المبرَّرين يتفضل الله أن يجعلهم، في ابنه الوحيد يسوع المسيح ومن أجله، شركاء في نعمة التبني: فيُحسبون في عدد أولاد الله ويتمتعون بحرياتهم وامتيازاتهم، ويحملون اسمه، وينالون روح التبني، ويتقدمون إلى عرش النعمة بجرأة، ويستطيعون أن يصرخوا «يا أبا الآب». ويُرحمون ويُحمون ويُعال بهم ويُؤدَّبون منه كأب، لكنهم لا يُطرحون أبداً، بل يُختمون ليوم الفداء، ويرثون المواعيد كورثة الخلاص الأبدي.', refs: ['Eph.1.5', 'Gal.4.4-5', 'Rom.8.17', 'John.1.12', 'Jer.14.9', '2Cor.6.18', 'Rev.3.12', 'Rom.8.15', 'Eph.3.12', 'Rom.5.2', 'Gal.4.6', 'Ps.103.13', 'Prov.14.26', 'Matt.6.30', 'Matt.6.32', '1Pet.5.7', 'Heb.12.6', 'Lam.3.31', 'Eph.4.30', 'Heb.6.12', '1Pet.1.3-4', 'Heb.1.14'] }
  ] },
  { n: 13, ar: 'التقديس', en: 'Of Sanctification', id: 'sanctification', secs: [
    { t: 'الذين دُعوا دعوة فعالة وتجددوا، وخُلق فيهم قلب جديد وروح جديد، يُقدَّسون أيضاً فعلياً وشخصياً، بقوة موت المسيح وقيامته، بكلمته وروحه الساكن فيهم: فيُهدم سلطان جسد الخطية كله، وتضعف شهواته وتُمات أكثر فأكثر، ويُحيون ويُقوَّون أكثر فأكثر في كل النعم المخلّصة، لممارسة القداسة الحقيقية التي بدونها لن يرى أحد الرب.', refs: ['1Cor.6.11', 'Acts.20.32', 'Phil.3.10', 'Rom.6.5-6', 'John.17.17', 'Eph.5.26', '2Thess.2.13', 'Rom.6.6', 'Rom.6.14', 'Gal.5.24', 'Rom.8.13', 'Col.1.11', 'Eph.3.16-19', '2Cor.7.1', 'Heb.12.14'] },
    { t: 'هذا التقديس يشمل الإنسان كله، لكنه غير كامل في هذه الحياة، إذ تبقى بقايا فساد في كل جزء. ومن هنا تنشأ حرب مستمرة لا مصالحة فيها: الجسد يشتهي ضد الروح، والروح ضد الجسد.', refs: ['1Thess.5.23', '1John.1.10', 'Rom.7.18', 'Rom.7.23', 'Phil.3.12', 'Gal.5.17', '1Pet.2.11'] },
    { t: 'في هذه الحرب، مع أن الفساد الباقي قد يغلب كثيراً لبعض الوقت، فإن الجزء المتجدد يغلب بالقوة المستمرة الآتية من روح المسيح المقدِّس. وهكذا ينمو القديسون في النعمة، مكمّلين القداسة في خوف الله.', refs: ['Rom.7.23', 'Rom.6.14', '1John.5.4', 'Eph.4.15-16', '2Pet.3.18', '2Cor.3.18', '2Cor.7.1'] }
  ] },
  { n: 14, ar: 'الإيمان الخلاصي', en: 'Of Saving Faith', id: 'faith', secs: [
    { t: 'نعمة الإيمان، التي بها يُمكَّن المختارون أن يؤمنوا لخلاص نفوسهم، هي عمل روح المسيح في قلوبهم، وتتولد عادة بخدمة الكلمة، وبها أيضاً، وبممارسة الأسرار والصلاة، تزداد وتتقوى.', refs: ['Heb.10.39', '2Cor.4.13', 'Eph.1.17-19', 'Eph.2.8', 'Rom.10.14', 'Rom.10.17', '1Pet.2.2', 'Acts.20.32', 'Rom.4.11', 'Luke.17.5', 'Rom.1.16-17'] },
    { t: 'بهذا الإيمان يصدّق المسيحي كل ما أُعلن في الكلمة أنه حق، لسلطان الله نفسه المتكلم فيها، ويتصرف بحسب ما يقوله كل جزء: يطيع الأوامر، ويرتعد أمام التهديدات، ويتمسك بمواعيد الله لهذه الحياة وللآتية. لكن الأعمال الرئيسية للإيمان المخلّص هي قبول المسيح وحده وتسلّمه والاستناد إليه للتبرير والتقديس والحياة الأبدية، بقوة عهد النعمة.', refs: ['John.4.42', '1Thess.2.13', '1John.5.10', 'Acts.24.14', 'Rom.16.26', 'Isa.66.2', 'Heb.11.13', '1Tim.4.8', 'John.1.12', 'Acts.16.31', 'Gal.2.20', 'Acts.15.11'] },
    { t: 'هذا الإيمان متفاوت في درجاته، ضعيف أو قوي. وقد يُهاجم ويضعف كثيراً وبطرق كثيرة، لكنه ينتصر. وهو ينمو في كثيرين حتى يبلغ يقيناً كاملاً بالمسيح، الذي هو رئيس إيماننا ومكمّله.', refs: ['Heb.5.13-14', 'Rom.4.19-20', 'Matt.6.30', 'Matt.8.10', 'Luke.22.31-32', 'Eph.6.16', '1John.5.4-5', 'Heb.6.11-12', 'Heb.10.22', 'Col.2.2', 'Heb.12.2'] }
  ] },
  { n: 15, ar: 'التوبة للحياة', en: 'Of Repentance unto Life', id: 'repentance', secs: [
    { t: 'التوبة للحياة نعمة إنجيلية، ويجب على كل خادم للإنجيل أن يكرز بتعليمها كما يكرز بتعليم الإيمان بالمسيح.', refs: ['Zech.12.10', 'Acts.11.18', 'Luke.24.47', 'Mark.1.15', 'Acts.20.21'] },
    { t: 'بالتوبة يرى الخاطئ ويشعر لا بخطر خطاياه فقط، بل بنجاستها وكراهيتها، إذ هي ضد طبيعة الله القدوسة وناموسه البار. ولأنه يدرك رحمة الله في المسيح للتائبين، يحزن على خطاياه ويبغضها حتى يرجع عنها كلها إلى الله، عازماً ومجتهداً أن يسلك معه في كل طرق وصاياه.', refs: ['Ezek.18.30-31', 'Ezek.36.31', 'Isa.30.22', 'Ps.51.4', 'Jer.31.18-19', 'Joel.2.12-13', 'Amos.5.15', 'Ps.119.128', '2Cor.7.11', 'Ps.119.6', 'Ps.119.59', 'Ps.119.106', 'Luke.1.6', '2Kgs.23.25'] },
    { t: 'مع أن التوبة ليست إيفاءً عن الخطية ولا سبباً للغفران، فالغفران عمل نعمة الله المجانية في المسيح، فهي ضرورية جداً لكل الخطاة، حتى إنه لا يُنتظر غفران لأحد بدونها.', refs: ['Ezek.36.31-32', 'Ezek.16.61-63', 'Hos.14.2', 'Hos.14.4', 'Rom.3.24', 'Eph.1.7', 'Luke.13.3', 'Luke.13.5', 'Acts.17.30-31'] },
    { t: 'كما أنه لا توجد خطية صغيرة لا تستحق الهلاك، كذلك لا توجد خطية عظيمة تجلب الهلاك على التائبين حقاً.', refs: ['Rom.6.23', 'Rom.5.12', 'Matt.12.36', 'Isa.55.7', 'Rom.8.1', 'Isa.1.16', 'Isa.1.18'] },
    { t: 'لا يكتفي الإنسان بتوبة عامة، بل واجبه أن يجتهد ليتوب عن خطاياه المعينة واحدة واحدة.', refs: ['Ps.19.13', 'Luke.19.8', '1Tim.1.13', '1Tim.1.15'] },
    { t: 'كما أن على كل إنسان أن يعترف سراً لله بخطاياه طالباً غفرانها، فينال الرحمة إذا تركها، كذلك من يسيء إلى أخيه أو إلى كنيسة المسيح يجب أن يكون مستعداً، باعتراف خاص أو علني وحزن على خطيته، أن يعلن توبته للمتضررين، وعليهم أن يتصالحوا معه ويقبلوه بمحبة.', refs: ['Ps.51.4-5', 'Ps.51.7', 'Ps.51.9', 'Ps.51.14', 'Ps.32.5-6', 'Prov.28.13', '1John.1.9', 'Jas.5.16', 'Luke.17.3-4', 'Josh.7.19', 'Ps.51.1-19', '2Cor.2.8'] }
  ] },
  { n: 16, ar: 'الأعمال الصالحة', en: 'Of Good Works', id: 'good-works', secs: [
    { t: 'الأعمال الصالحة هي فقط ما أمر به الله في كلمته المقدسة، لا ما ابتكره الناس من دون أمر منه، بغيرة عمياء أو بحجة نية حسنة.', refs: ['Mic.6.8', 'Rom.12.2', 'Heb.13.21', 'Matt.15.9', 'Isa.29.13', '1Pet.1.18', 'Rom.10.2', 'John.16.2', '1Sam.15.21-23'] },
    { t: 'هذه الأعمال الصالحة، المعمولة طاعة لوصايا الله، هي ثمار الإيمان الحي الحقيقي وبيّناته. بها يُظهر المؤمنون شكرهم، ويقوّون يقينهم، ويبنون إخوتهم، ويزيّنون اعتراف الإنجيل، ويسدّون أفواه المعاندين، ويمجدون الله، الذين هم صنعته، مخلوقين في المسيح يسوع لهذه الأعمال، حتى يكون لهم ثمر للقداسة، والنهاية حياة أبدية.', refs: ['Jas.2.18', 'Jas.2.22', 'Ps.116.12-13', '1Pet.2.9', '1John.2.3', '1John.2.5', '2Pet.1.5-10', '2Cor.9.2', 'Matt.5.16', 'Titus.2.5', 'Titus.2.9-12', '1Tim.6.1', '1Pet.2.15', '1Pet.2.12', 'Phil.1.11', 'John.15.8', 'Eph.2.10', 'Rom.6.22'] },
    { t: 'قدرتهم على عمل الصلاح ليست منهم على الإطلاق، بل كلها من روح المسيح. ولكي يقدروا عليه، يلزم، إلى جانب النعم التي نالوها، تأثير فعلي من الروح نفسه ليعمل فيهم أن يريدوا وأن يعملوا. ومع ذلك لا يجوز أن يتكاسلوا كأنهم غير مطالبين بشيء إلا بتحريك خاص من الروح، بل عليهم أن يجتهدوا في إضرام نعمة الله التي فيهم.', refs: ['John.15.4-6', 'Ezek.36.26-27', 'Phil.2.13', 'Phil.4.13', '2Cor.3.5', 'Phil.2.12', 'Heb.6.11-12', '2Pet.1.3', '2Pet.1.5', '2Pet.1.10-11', 'Isa.64.7', '2Tim.1.6', 'Acts.26.6-7', 'Jude.1.20-21'] },
    { t: 'الذين يبلغون في طاعتهم أقصى ما يمكن في هذه الحياة، أبعد ما يكونون عن أن يقدّموا فائضاً أو يعملوا أكثر مما يطلبه الله، فهم يقصرون عن كثير مما هم مطالبون به.', refs: ['Luke.17.10', 'Neh.13.22', 'Job.9.2-3', 'Gal.5.17'] },
    { t: 'لا نستطيع بأفضل أعمالنا أن نستحق غفران الخطية أو الحياة الأبدية من يد الله، بسبب الفارق العظيم بين أعمالنا والمجد الآتي، والمسافة اللانهائية بيننا وبين الله. فحين نعمل كل ما نقدر عليه، لا نكون قد عملنا إلا واجبنا، ونحن عبيد بطالون. ولأن ما فيها من صلاح هو من روحه، وما نعمله نحن فيه نجاسة وخلط بضعف ونقص كثير، فلا يحتمل صرامة دينونة الله.', refs: ['Rom.3.20', 'Rom.4.2', 'Rom.4.4', 'Rom.4.6', 'Eph.2.8-9', 'Titus.3.5-7', 'Rom.8.18', 'Ps.16.2', 'Job.22.2-3', 'Job.35.7-8', 'Luke.17.10', 'Gal.5.22-23', 'Isa.64.6', 'Gal.5.17', 'Rom.7.15', 'Rom.7.18', 'Ps.143.2', 'Ps.130.3'] },
    { t: 'ومع ذلك، لأن أشخاص المؤمنين مقبولون في المسيح، فأعمالهم الصالحة مقبولة فيه أيضاً. لا كأنها بلا لوم أو ملامة تماماً في نظر الله، بل لأنه، إذ ينظر إليها في ابنه، يُسر أن يقبل ويكافئ ما هو مخلص، وإن رافقته ضعفات ونقائص كثيرة.', refs: ['Eph.1.6', '1Pet.2.5', 'Exod.28.38', 'Gen.4.4', 'Heb.11.4', 'Job.9.20', 'Ps.143.2', 'Heb.13.20-21', '2Cor.8.12', 'Heb.6.10', 'Matt.25.21', 'Matt.25.23'] },
    { t: 'الأعمال التي يعملها غير المتجددين، وإن كانت في ذاتها مما أمر به الله ونافعة لهم ولغيرهم، لأنها لا تصدر من قلب طهّره الإيمان، ولا تُعمل بالطريقة الصحيحة حسب الكلمة، ولا للغاية الصحيحة أي مجد الله، فهي خاطئة ولا ترضي الله ولا تؤهل إنساناً لنيل النعمة منه. ومع ذلك فإهمالهم لها أكثر خطية وأكثر إغضاباً لله.', refs: ['2Kgs.10.30-31', '1Kgs.21.27', '1Kgs.21.29', 'Phil.1.15-16', 'Phil.1.18', 'Gen.4.5', 'Heb.11.4', 'Heb.11.6', '1Cor.13.3', 'Isa.1.12', 'Matt.6.2', 'Matt.6.5', 'Matt.6.16', 'Hag.2.14', 'Titus.1.15', 'Amos.5.21-22', 'Hos.1.4', 'Rom.9.16', 'Titus.3.5', 'Ps.14.4', 'Ps.36.3', 'Job.21.14-15', 'Matt.25.41-43', 'Matt.25.45', 'Matt.23.23'] }
  ] },
  { n: 17, ar: 'مثابرة القديسين', en: 'Of the Perseverance of the Saints', id: 'perseverance', secs: [
    { t: 'الذين قبلهم الله في المحبوب، ودعاهم دعوة فعالة، وقدّسهم بروحه، لا يمكن أن يسقطوا كلياً ولا نهائياً من حالة النعمة، بل سيثابرون فيها بكل يقين إلى النهاية، ويخلصون أبدياً.', refs: ['Phil.1.6', '2Pet.1.10', 'John.10.28-29', '1John.3.9', '1Pet.1.5', '1Pet.1.9'] },
    { t: 'مثابرة القديسين هذه لا تعتمد على إرادتهم الحرة، بل على ثبات قضاء الاختيار النابع من محبة الله الآب المجانية الثابتة، وعلى فاعلية استحقاق يسوع المسيح وشفاعته، وعلى سكنى الروح ونسل الله فيهم، وعلى طبيعة عهد النعمة. ومن كل هذا ينبع يقينها وعصمتها.', refs: ['2Tim.2.18-19', 'Jer.31.3', 'Heb.10.10', 'Heb.10.14', 'Heb.13.20-21', 'Heb.9.12-15', 'Rom.8.33-39', 'John.17.11', 'John.17.24', 'Luke.22.32', 'Heb.7.25', 'John.14.16-17', '1John.2.27', '1John.3.9', 'Jer.32.40', 'John.10.28', '2Thess.3.3', '1John.2.19'] },
    { t: 'ومع ذلك قد يسقطون، بتجارب الشيطان والعالم، وبغلبة الفساد الباقي فيهم، وبإهمال وسائل حفظهم، في خطايا شنيعة، ويستمرون فيها بعض الوقت. وبذلك يجلبون غضب الله ويُحزنون روحه القدوس، ويُحرمون من بعض نعمهم وتعزياتهم، وتتقسى قلوبهم وتُجرح ضمائرهم، ويسيئون إلى غيرهم ويعثرونهم، ويجلبون على أنفسهم أحكاماً زمنية.', refs: ['Matt.26.70', 'Matt.26.72', 'Matt.26.74', 'Ps.51.14', 'Isa.64.5', 'Isa.64.7', 'Isa.64.9', '2Sam.11.27', 'Eph.4.30', 'Ps.51.8', 'Ps.51.10', 'Ps.51.12', 'Rev.2.4', 'Song.5.2-4', 'Isa.63.17', 'Mark.6.52', 'Mark.16.14', 'Ps.32.3-4', '2Sam.12.14', 'Ps.89.31-32', '1Cor.11.32'] }
  ] },
  { n: 18, ar: 'يقين النعمة والخلاص', en: 'Of Assurance of Grace and Salvation', id: 'assurance', secs: [
    { t: 'مع أن المرائين وغير المتجددين قد يخدعون أنفسهم عبثاً بآمال كاذبة وثقة جسدية أنهم في رضا الله وفي حالة خلاص، وهو رجاء يهلك، فإن الذين يؤمنون حقاً بالرب يسوع ويحبونه بإخلاص، ويجتهدون أن يسلكوا أمامه بضمير صالح، قد يتيقنون في هذه الحياة يقيناً أنهم في حالة النعمة، ويفرحون على رجاء مجد الله، وهذا الرجاء لن يخزيهم أبداً.', refs: ['Job.8.13-14', 'Mic.3.11', 'Deut.29.19', 'John.8.41', 'Matt.7.22-23', '1John.2.3', '1John.3.14', '1John.3.18-19', '1John.3.21', '1John.3.24', '1John.5.13', 'Rom.5.2', 'Rom.5.5'] },
    { t: 'هذا اليقين ليس مجرد اقتناع مُحتمل أو تخمين مبني على رجاء ممكن الخطأ، بل يقين إيمان معصوم، مؤسس على حق الله في مواعيد الخلاص، وعلى البيّنة الداخلية للنعم التي تُعطى لها هذه المواعيد، وعلى شهادة روح التبني الذي يشهد مع أرواحنا أننا أولاد الله، وهو عربون ميراثنا الذي به نُختم ليوم الفداء.', refs: ['Heb.6.11', 'Heb.6.19', 'Heb.6.17-18', '2Pet.1.4-5', '2Pet.1.10-11', '1John.2.3', '1John.3.14', '2Cor.1.12', 'Rom.8.15-16', 'Eph.1.13-14', 'Eph.4.30', '2Cor.1.21-22'] },
    { t: 'هذا اليقين المعصوم لا يخص جوهر الإيمان، فقد ينتظر المؤمن الحقيقي طويلاً ويصارع صعوبات كثيرة قبل أن يناله. لكنه، إذ يُمكَّن بالروح أن يعرف ما وهبه الله مجاناً، يستطيع أن يبلغه بالاستخدام الصحيح للوسائل العادية، دون إعلان خاص. لذلك واجب كل واحد أن يجتهد ليجعل دعوته واختياره ثابتين، فيتسع قلبه بالسلام والفرح في الروح القدس، والمحبة والشكر لله، والقوة والفرح في واجبات الطاعة، وهي الثمار الطبيعية لهذا اليقين. وهو أبعد ما يكون عن أن يدفع الناس إلى التهاون.', refs: ['1John.5.13', 'Isa.50.10', 'Mark.9.24', 'Ps.88.1-18', 'Ps.77.1-12', '1Cor.2.12', '1John.4.13', 'Heb.6.11-12', 'Eph.3.17-19', '2Pet.1.10', 'Rom.5.1-2', 'Rom.5.5', 'Rom.14.17', 'Rom.15.13', 'Eph.1.3-4', 'Ps.4.6-7', 'Ps.119.32', '1John.2.1-2', 'Rom.6.1-2', 'Titus.2.11-12', 'Titus.2.14', '2Cor.7.1', 'Rom.8.1', 'Rom.8.12', '1John.3.2-3', 'Ps.130.4', '1John.1.6-7'] },
    { t: 'قد يهتز يقين المؤمنين الحقيقيين بالخلاص ويضعف وينقطع بطرق مختلفة: بإهمال حفظه، أو بالسقوط في خطية معينة تجرح الضمير وتُحزن الروح، أو بتجربة مفاجئة أو عنيفة، أو بحجب الله نور وجهه عنهم. لكنهم لا يُحرمون أبداً من نسل الله وحياة الإيمان، ومحبة المسيح والإخوة، وإخلاص القلب وضمير الواجب، التي منها، بعمل الروح، يُحيى هذا اليقين في وقته، وبها في الوقت نفسه يُحفظون من اليأس الكامل.', refs: ['Song.5.2-3', 'Song.5.6', 'Ps.51.8', 'Ps.51.12', 'Ps.51.14', 'Eph.4.30-31', 'Ps.77.1-10', 'Matt.26.69-72', 'Ps.31.22', 'Ps.88.1-18', 'Isa.50.10', '1John.3.9', 'Luke.22.32', 'Job.13.15', 'Ps.73.15', 'Ps.51.8', 'Ps.51.12', 'Isa.50.10', 'Mic.7.7-9', 'Jer.32.40', 'Isa.54.7-10', 'Ps.22.1', 'Ps.88.1-18'] }
  ] },
  { n: 19, ar: 'ناموس الله', en: 'Of the Law of God', id: 'law', secs: [
    { t: 'أعطى الله آدم ناموساً كعهد أعمال، ألزمه به هو ونسله بطاعة شخصية كاملة دقيقة دائمة، ووعد بالحياة لمن يتممه، وهدد بالموت من يتعداه، ووهبه القدرة والطاقة على حفظه.', refs: ['Gen.1.26-27', 'Gen.2.17', 'Rom.2.14-15', 'Rom.10.5', 'Rom.5.12', 'Rom.5.19', 'Gal.3.10', 'Gal.3.12', 'Eccl.7.29', 'Job.28.28'] },
    { t: 'هذا الناموس، بعد السقوط، استمر قاعدة كاملة للبر، وأعلنه الله بهذه الصفة على جبل سيناء في عشر وصايا مكتوبة في لوحين: الأربع الأولى تحوي واجبنا نحو الله، والست الباقية واجبنا نحو الإنسان.', refs: ['Jas.1.25', 'Jas.2.8', 'Jas.2.10-12', 'Rom.13.8-9', 'Deut.5.32', 'Deut.10.4', 'Exod.34.1', 'Matt.22.37-40'] },
    { t: 'إلى جانب هذا الناموس المسمى عادة الأدبي، سُر الله أن يعطي شعب إسرائيل، ككنيسة تحت الوصاية، نواميس طقسية تحتوي فرائض رمزية متعددة: بعضها للعبادة، ترمز مسبقاً إلى المسيح ونعمته وأعماله وآلامه وفوائده، وبعضها يقدم تعليمات متنوعة في الواجبات الأدبية. وكل هذه النواميس الطقسية أُبطلت الآن في العهد الجديد.', refs: ['Heb.9.1-28', 'Heb.10.1', 'Gal.4.1-3', 'Col.2.17', '1Cor.5.7', '2Cor.6.17', 'Jude.1.23', 'Col.2.14', 'Col.2.16-17', 'Dan.9.27', 'Eph.2.15-16'] },
    { t: 'وأعطاهم أيضاً، كجماعة سياسية، نواميس قضائية متنوعة انتهت مع انتهاء دولة ذلك الشعب، فلا تُلزم أحداً الآن إلا بقدر ما تتطلبه العدالة العامة التي فيها.', refs: ['Exod.21.1-36', 'Exod.22.1-29', 'Gen.49.10', '1Pet.2.13-14', 'Matt.5.17', 'Matt.5.38-39', '1Cor.9.8-10'] },
    { t: 'الناموس الأدبي يُلزم الجميع إلى الأبد، المبرَّرين وغيرهم، بالطاعة له. لا من جهة مضمونه فقط، بل أيضاً من جهة سلطان الله الخالق المعطي له. والمسيح في الإنجيل لا يحل هذا الالتزام بأي حال، بل يقوّيه كثيراً.', refs: ['Rom.13.8-10', 'Eph.6.2', '1John.2.3-4', '1John.2.7-8', 'Jas.2.10-11', 'Matt.5.17-19', 'Jas.2.8', 'Rom.3.31'] },
    { t: 'مع أن المؤمنين الحقيقيين ليسوا تحت الناموس كعهد أعمال ليتبرروا به أو يُدانوا، فهو نافع جداً لهم ولغيرهم: كقاعدة حياة تعلّمهم مشيئة الله وواجبهم وتوجههم، وتكشف لهم فساد طبيعتهم وقلوبهم وحياتهم فيتضعوا ويبغضوا الخطية، ويروا حاجتهم إلى المسيح وكمال طاعته. وتهديداته تُظهر ما تستحقه خطاياهم، ومواعيده تُظهر رضا الله عن الطاعة. فكون الإنسان يعمل الخير ويمتنع عن الشر لأن الناموس يشجّع على هذا ويمنع ذاك، لا يعني أنه تحت الناموس لا تحت النعمة.', refs: ['Rom.6.14', 'Gal.2.16', 'Gal.3.13', 'Gal.4.4-5', 'Acts.13.39', 'Rom.8.1', 'Rom.7.12', 'Rom.7.22', 'Rom.7.25', 'Ps.119.4-6', '1Cor.7.19', 'Gal.5.14', 'Gal.5.16', 'Gal.5.18-23', 'Rom.7.7', 'Rom.3.20', 'Jas.1.23-25', 'Rom.7.9', 'Rom.7.14', 'Rom.7.24', 'Gal.3.24', 'Ps.37.11', 'Matt.5.5', 'Ps.19.11', 'Rom.6.12', 'Rom.6.14', '1Pet.3.8-12', 'Heb.12.28-29'] },
    { t: 'هذه الاستخدامات للناموس لا تتعارض مع نعمة الإنجيل، بل تتوافق معها بعذوبة، إذ يُخضع روح المسيح إرادة الإنسان ويمكّنه أن يعمل بحرية وفرح ما تطلبه مشيئة الله المعلنة في الناموس.', refs: ['Gal.3.21', 'Ezek.36.27', 'Heb.8.10', 'Jer.31.33'] }
  ] },
  { n: 20, ar: 'الحرية المسيحية وحرية الضمير', en: 'Of Christian Liberty, and Liberty of Conscience', id: 'liberty', secs: [
    { t: 'الحرية التي اشتراها المسيح للمؤمنين في زمن الإنجيل هي تحررهم من ذنب الخطية، ومن غضب الله المدين، ولعنة الناموس الأدبي، وتحررهم من هذا العالم الحاضر الشرير، ومن عبودية الشيطان وسلطان الخطية، ومن شر الضيقات، وشوكة الموت، وغلبة القبر، والهلاك الأبدي. وتشمل أيضاً حرية الاقتراب إلى الله، وطاعتهم له لا بخوف عبودي، بل بمحبة بنوية وذهن راغب. وكل هذا كان للمؤمنين تحت الناموس أيضاً. أما في العهد الجديد فاتسعت حرية المسيحيين أكثر، بتحررهم من نير الناموس الطقسي، وبجرأة أعظم في الاقتراب إلى عرش النعمة، وبعطايا أكمل من روح الله الحر.', refs: ['Titus.2.14', '1Thess.1.10', 'Gal.3.13', 'Gal.1.4', 'Col.1.13', 'Acts.26.18', 'Rom.6.14', 'Rom.8.28', 'Ps.119.71', '1Cor.15.54-57', 'Rom.8.1', 'Rom.5.1-2', 'Rom.8.14-15', '1John.4.18', 'Gal.3.9', 'Gal.3.14', 'Gal.4.1-3', 'Gal.4.6-7', 'Gal.5.1', 'Acts.15.10-11', 'Heb.4.14', 'Heb.4.16', 'Heb.10.19-22', 'John.7.38-39', '2Cor.3.13', '2Cor.3.17-18'] },
    { t: 'الله وحده رب الضمير، وقد حرره من تعاليم البشر ووصاياهم التي تخالف كلمته أو تُضاف إليها في أمور الإيمان والعبادة. فتصديق هذه التعاليم أو طاعة هذه الوصايا من أجل الضمير خيانة للحرية الحقيقية للضمير. وطلب إيمان أعمى أو طاعة مطلقة عمياء تدمير لحرية الضمير وللعقل أيضاً.', refs: ['Jas.4.12', 'Rom.14.4', 'Acts.4.19', 'Acts.5.29', '1Cor.7.23', 'Matt.23.8-10', '2Cor.1.24', 'Matt.15.9', 'Col.2.20', 'Col.2.22-23', 'Gal.1.10', 'Gal.2.4-5', 'Gal.5.1', 'Rom.10.17', 'Rom.14.23', 'Isa.8.20', 'Acts.17.11', 'John.4.22', 'Hos.5.11', 'Rev.13.12', 'Rev.13.16-17', 'Jer.8.9'] },
    { t: 'الذين، بحجة الحرية المسيحية، يمارسون أي خطية أو يحتضنون أي شهوة، يهدمون بهذا غاية الحرية المسيحية. وهي أننا، إذ نجونا من أيدي أعدائنا، نعبده بلا خوف، بالقداسة والبر قدامه كل أيام حياتنا.', refs: ['Gal.5.13', '1Pet.2.16', '2Pet.2.19', 'John.8.34', 'Luke.1.74-75'] },
    { t: 'ولأن السلطات التي رتبها الله، والحرية التي اشتراها المسيح، لم يقصد الله أن تهدم إحداهما الأخرى، بل أن تسند كل منهما الأخرى وتحفظها، فالذين يقاومون أي سلطة شرعية أو ممارستها الشرعية، مدنية كانت أو كنسية، بحجة الحرية المسيحية، يقاومون ترتيب الله. ومن ينشرون آراء أو ممارسات تخالف نور الطبيعة، أو المبادئ المعروفة للمسيحية في الإيمان والعبادة والسلوك، أو قوة التقوى، أو تهدم السلام الخارجي والنظام الذي رتبه المسيح في كنيسته، قد يُحاسَبون عليها قانونياً وتُتخذ ضدهم إجراءات بتأديبات الكنيسة وبسلطة الحاكم المدني. (وقد حذفت المراجعة الأمريكية سنة 1788 عبارة "وبسلطة الحاكم المدني".)', refs: ['Matt.12.25', '1Pet.2.13-14', '1Pet.2.16', 'Rom.13.1-8', 'Heb.13.17', 'Rom.1.32', '1Cor.5.1', '1Cor.5.5', '1Cor.5.11', '1Cor.5.13', '2John.1.10-11', '2Thess.3.14', '1Tim.6.3-5', 'Titus.1.10-11', 'Titus.1.13', 'Titus.3.10', 'Matt.18.15-17', '1Tim.1.19-20', 'Rev.2.2', 'Rev.2.14-15', 'Rev.2.20', 'Rev.3.9'] }
  ] },
  { n: 21, ar: 'العبادة الدينية ويوم السبت', en: 'Of Religious Worship, and the Sabbath Day', id: 'worship', also: 'lords-day', secs: [
    { t: 'نور الطبيعة يُظهر أن هناك إلهاً له السيادة على الكل، وهو صالح ويصنع الخير للكل، فيجب أن يُخاف ويُحب ويُسبح ويُدعى ويُتكل عليه ويُخدم بكل القلب والنفس والقوة. لكن الطريقة المقبولة لعبادة الإله الحقيقي رتبها هو نفسه، وحددها بمشيئته المعلنة، فلا يجوز أن يُعبد حسب تخيلات البشر واختراعاتهم، أو اقتراحات الشيطان، تحت أي تمثيل منظور، أو بأي طريقة أخرى لم يأمر بها الكتاب المقدس.', refs: ['Rom.1.20', 'Acts.17.24', 'Ps.119.68', 'Jer.10.7', 'Ps.31.23', 'Ps.18.3', 'Rom.10.12', 'Ps.62.8', 'Josh.24.14', 'Mark.12.33', 'Deut.12.32', 'Matt.15.9', 'Acts.17.25', 'Matt.4.9-10', 'Deut.4.15-20', 'Exod.20.4-6', 'Col.2.23'] },
    { t: 'العبادة الدينية تُقدَّم لله الآب والابن والروح القدس، وله وحده، لا للملائكة ولا للقديسين ولا لأي مخلوق آخر. ومنذ السقوط لا تكون إلا بوسيط، ولا بأي وساطة أخرى إلا وساطة المسيح وحده.', refs: ['Matt.4.10', 'John.5.23', '2Cor.13.14', 'Col.2.18', 'Rev.19.10', 'Rom.1.25', 'John.14.6', '1Tim.2.5', 'Eph.2.18', 'Col.3.17'] },
    { t: 'الصلاة مع الشكر، وهي جزء خاص من العبادة الدينية، يطلبها الله من كل الناس. ولكي تُقبل يجب أن تُقدَّم باسم الابن، وبمعونة روحه، وحسب مشيئته، بفهم وتوقير وتواضع وحرارة وإيمان ومحبة ومثابرة. وإذا كانت جهرية، فبلغة مفهومة.', refs: ['Phil.4.6', 'Ps.65.2', 'John.14.13-14', '1Pet.2.5', 'Rom.8.26', '1John.5.14', 'Ps.47.7', 'Eccl.5.1-2', 'Heb.12.28', 'Gen.18.27', 'Jas.5.16', 'Jas.1.6-7', 'Mark.11.24', 'Matt.6.12', 'Matt.6.14-15', 'Col.4.2', 'Eph.6.18', '1Cor.14.14'] },
    { t: 'الصلاة تُقدَّم لأجل أمور مشروعة، ولأجل كل أنواع الناس الأحياء أو الذين سيعيشون لاحقاً، لكن لا لأجل الأموات، ولا لأجل من يُعرف أنهم ارتكبوا الخطية التي للموت.', refs: ['1John.5.14', '1Tim.2.1-2', 'John.17.20', '2Sam.7.29', 'Ruth.4.12', '2Sam.12.21-23', 'Luke.16.25-26', 'Rev.14.13', '1John.5.16'] },
    { t: 'قراءة الكتاب بخشوع، والكرازة الأمينة، والاستماع الواعي للكلمة طاعة لله بفهم وإيمان وتوقير، وترنيم المزامير بنعمة في القلب، وكذلك الممارسة الصحيحة والقبول اللائق للأسرار التي رتبها المسيح، كلها أجزاء من العبادة الدينية العادية لله. إلى جانب الأقسام الدينية والنذور والأصوام الجماعية والشكر في المناسبات الخاصة، التي تُمارس في أوقاتها بطريقة مقدسة.', refs: ['Acts.15.21', 'Rev.1.3', '2Tim.4.2', 'Jas.1.22', 'Acts.10.33', 'Matt.13.19', 'Heb.4.2', 'Isa.66.2', 'Col.3.16', 'Eph.5.19', 'Jas.5.13', 'Matt.28.19', '1Cor.11.23-29', 'Acts.2.42', 'Deut.6.13', 'Neh.10.29', 'Isa.19.21', 'Eccl.5.4-5', 'Joel.2.12', 'Esth.4.16', 'Matt.9.15', '1Cor.7.5', 'Ps.107.1-43', 'Esth.9.22'] },
    { t: 'لا الصلاة ولا أي جزء آخر من العبادة الدينية مقيد الآن، في زمن الإنجيل، بمكان معين أو مُقبول أكثر بسببه. بل يُعبد الله في كل مكان بالروح والحق: في العائلات يومياً، وفي الخلوة كل واحد لنفسه، وبوقار أعظم في الاجتماعات العامة، التي لا يجوز إهمالها أو تركها عمداً حين يدعونا الله إليها بكلمته أو عنايته.', refs: ['John.4.21', 'Mal.1.11', '1Tim.2.8', 'John.4.23-24', 'Jer.10.25', 'Deut.6.6-7', 'Job.1.5', '2Sam.6.18', '2Sam.6.20', '1Pet.3.7', 'Acts.10.2', 'Matt.6.11', 'Matt.6.6', 'Eph.6.18', 'Isa.56.6-7', 'Heb.10.25', 'Ps.100.4', 'Ps.84.1-12', 'Luke.4.16', 'Acts.13.42', 'Acts.2.42'] },
    { t: 'كما أنه من ناموس الطبيعة أن يُخصص جزء مناسب من الوقت لعبادة الله، كذلك في كلمته، بوصية إيجابية أدبية دائمة تُلزم كل البشر في كل العصور، عيّن يوماً من كل سبعة ليكون سبتاً يُحفظ مقدساً له. وكان منذ بداية العالم إلى قيامة المسيح هو اليوم الأخير من الأسبوع، ومنذ قيامة المسيح تغيّر إلى اليوم الأول من الأسبوع، المسمى في الكتاب يوم الرب، ويُحفظ إلى نهاية العالم كسبت مسيحي.', refs: ['Exod.20.8', 'Exod.20.10-11', 'Isa.56.2', 'Isa.56.4', 'Isa.56.6-7', 'Gen.2.2-3', '1Cor.16.1-2', 'Acts.20.7', 'Rev.1.10', 'Matt.5.17-18'] },
    { t: 'يُحفظ هذا السبت مقدساً للرب حين يهيئ الناس قلوبهم كما يليق، ويرتبون أمورهم العادية مسبقاً، فيستريحون اليوم كله استراحة مقدسة من أعمالهم وكلامهم وأفكارهم عن الأشغال والترفيهات العالمية، ويقضون الوقت كله في ممارسات العبادة العامة والخاصة، وفي أعمال الضرورة والرحمة.', refs: ['Exod.20.8', 'Exod.16.23', 'Exod.16.25-26', 'Exod.16.29-30', 'Exod.31.15-17', 'Isa.58.13', 'Neh.13.15-22', 'Matt.12.1-13'] }
  ] },
  { n: 22, ar: 'الأقسام الشرعية والنذور', en: 'Of Lawful Oaths and Vows', id: 'oaths', secs: [
    { t: 'القسم الشرعي جزء من العبادة الدينية، وفيه، في مناسبة عادلة، يدعو الحالف الله رسمياً ليشهد على ما يؤكده أو يعد به، وليدينه حسب صدق ما يحلف به أو كذبه.', refs: ['Deut.10.20', 'Exod.20.7', 'Lev.19.12', '2Cor.1.23', '2Chr.6.22-23'] },
    { t: 'اسم الله وحده هو الذي يجوز للناس أن يحلفوا به، ويجب أن يُستخدم بكل خوف مقدس وتوقير. فالحلف عبثاً أو باستهانة بهذا الاسم المجيد المخوف، أو الحلف بأي شيء آخر، خطية يجب أن تُكره. ومع ذلك، كما أن القسم في الأمور ذات الوزن والأهمية مؤيَّد بكلمة الله في العهد الجديد كما في القديم، فالقسم الشرعي الذي تفرضه سلطة شرعية في مثل هذه الأمور يجب أن يُؤدى.', refs: ['Deut.6.13', 'Exod.20.7', 'Jer.5.7', 'Matt.5.34', 'Matt.5.37', 'Jas.5.12', 'Heb.6.16', '2Cor.1.23', 'Isa.65.16', '1Kgs.8.31', 'Neh.13.25', 'Ezra.10.5'] },
    { t: 'من يحلف يجب أن يزن بجدية خطورة هذا العمل العظيم، ولا يؤكد فيه إلا ما هو مقتنع تماماً أنه حق. ولا يجوز لأحد أن يلزم نفسه بقسم بأي شيء إلا ما هو صالح وعادل، وما يؤمن أنه كذلك، وما يقدر ويعزم أن يتممه. ومع ذلك فرفض القسم في أمر صالح وعادل، إذا فرضته سلطة شرعية، خطية.', refs: ['Exod.20.7', 'Jer.4.2', 'Gen.24.2-3', 'Gen.24.5-6', 'Gen.24.8-9', 'Num.5.19', 'Num.5.21', 'Neh.5.12', 'Exod.22.7-11'] },
    { t: 'يجب أن يُؤدى القسم بالمعنى الواضح العادي للكلمات، دون مراوغة أو تحفظ ذهني. ولا يمكن أن يُلزم بالخطية، لكنه في كل ما ليس خطية يُلزم بتتميمه ولو كان ضد مصلحة الحالف. ولا يجوز نقضه ولو أُعطي لهراطقة أو غير مؤمنين.', refs: ['Jer.4.2', 'Ps.24.4', '1Sam.25.22', '1Sam.25.32-34', 'Ps.15.4', 'Ezek.17.16', 'Ezek.17.18-19', 'Josh.9.18-19', '2Sam.21.1'] },
    { t: 'النذر من طبيعة مشابهة للقسم الموعود به، ويجب أن يُقدم بنفس الحرص الديني، ويُتمم بنفس الأمانة.', refs: ['Isa.19.21', 'Eccl.5.4-6', 'Ps.61.8', 'Ps.66.13-14'] },
    { t: 'لا يُنذر لأي مخلوق، بل لله وحده. ولكي يكون مقبولاً يجب أن يُقدم طوعاً، بإيمان وضمير الواجب، شكراً على رحمة نالها، أو للحصول على ما نريد، وبه نلزم أنفسنا بشكل أشد بالواجبات اللازمة، أو بأمور أخرى بقدر ما تساعدنا عليها.', refs: ['Ps.76.11', 'Jer.44.25-26', 'Deut.23.21-23', 'Ps.50.14', 'Gen.28.20-22', '1Sam.1.11', 'Ps.66.13-14', 'Ps.132.2-5'] },
    { t: 'لا يجوز لأحد أن ينذر عمل أي شيء تحرّمه كلمة الله، أو ما يعيق أي واجب أمرت به، أو ما ليس في قدرته، أو ما لم يعطه الله وعداً بالقدرة عليه. ومن هذه الجهة فنذور الرهبنة البابوية بالعزوبية الدائمة والفقر المُعلن والطاعة النظامية، أبعد ما تكون عن درجات كمال أعلى، بل هي فخاخ خرافية وخاطئة لا يجوز للمسيحي أن يورط نفسه فيها.', refs: ['Acts.23.12', 'Acts.23.14', 'Mark.6.26', 'Num.30.5', 'Num.30.8', 'Num.30.12-13', 'Matt.19.11-12', '1Cor.7.2', '1Cor.7.9', 'Eph.4.28', '1Thess.4.11-12', '1Cor.7.23'] }
  ] },
  { n: 23, ar: 'السلطة المدنية', en: 'Of the Civil Magistrate', id: 'magistrate', secs: [
    { t: 'الله، الرب الأعلى وملك العالم كله، رتب حكاماً مدنيين ليكونوا تحت سلطانه وفوق الشعب، لمجده وللخير العام. ولهذه الغاية سلّحهم بسلطة السيف لحماية الصالحين وتشجيعهم، ولمعاقبة فاعلي الشر.', refs: ['Rom.13.1-4', '1Pet.2.13-14'] },
    { t: 'يجوز للمسيحيين أن يقبلوا وظيفة الحاكم ويمارسوها حين يُدعون إليها. وفي إدارتها عليهم أن يحفظوا التقوى والعدل والسلام بشكل خاص، حسب النواميس الصالحة لكل دولة. ولهذه الغاية يجوز لهم الآن، في العهد الجديد، أن يشنوا الحرب في المناسبات العادلة والضرورية.', refs: ['Prov.8.15-16', 'Rom.13.1-2', 'Rom.13.4', 'Ps.2.10-12', '1Tim.2.2', 'Ps.82.3-4', '2Sam.23.3', '1Pet.2.13', 'Luke.3.14', 'Rom.13.4', 'Matt.8.9-10', 'Acts.10.1-2', 'Rev.17.14', 'Rev.17.16'] },
    { t: 'الحكام المدنيون لا يأخذون لأنفسهم خدمة الكلمة والأسرار، ولا سلطة مفاتيح ملكوت السماوات، ولا يتدخلون بأي حال في أمور الإيمان. ومع ذلك، كآباء مرضعين، واجبهم أن يحموا كنيسة ربنا المشترك دون تفضيل أي طائفة مسيحية على غيرها، بحيث يتمتع كل الأشخاص الكنسيين بحرية كاملة غير منقوصة في أداء وظائفهم المقدسة دون عنف أو خطر. وكما أقام المسيح في كنيسته حكماً منتظماً وتأديباً، فلا يجوز لأي قانون دولة أن يتدخل أو يعيق ممارسته الواجبة بين أعضاء أي طائفة مسيحية حسب اعترافها وإيمانها. وواجبهم أن يحموا أشخاص كل شعبهم وسمعتهم، فلا يُسمح لأحد بحجة الدين أو عدم الإيمان أن يسيء أو يعنّف أو يؤذي غيره، وأن يحرصوا أن تُعقد كل الاجتماعات الدينية والكنسية دون إزعاج. (هذا الفصل هنا بحسب المراجعة الأمريكية سنة 1788. أما نص 1646 الأصلي في هذا القسم فجعل على الحاكم واجب حفظ الوحدة والسلام في الكنيسة، وحفظ حق الله نقياً كاملاً، وقمع التجاديف والهرطقات، وأعطاه سلطة الدعوة إلى المجامع وحضورها.)', refs: ['2Chr.26.18', 'Matt.18.17', 'Matt.16.19', '1Cor.12.28-29', 'Eph.4.11-12', '1Cor.4.1-2', 'Rom.10.15', 'Heb.5.4', 'John.18.36', 'Isa.49.23', 'Ps.105.15', 'Acts.18.14-16', 'Matt.28.19-20', 'Ps.105.15', '2Sam.23.3', '1Tim.2.1', 'Rom.13.4'] },
    { t: 'واجب الشعب أن يصلّي لأجل الحكام، ويكرّم أشخاصهم، ويدفع لهم الجزية وغيرها من المستحقات، ويطيع أوامرهم الشرعية، ويخضع لسلطتهم من أجل الضمير. والاختلاف في الدين أو عدم الإيمان لا يُبطل سلطة الحاكم العادلة الشرعية، ولا يحرر الشعب من الطاعة الواجبة له. والأشخاص الكنسيون ليسوا مستثنين من ذلك، وأقل منهم بكثير البابا الذي ليس له أي سلطة أو ولاية عليهم في ممالكهم أو على أي من شعبهم، وأقل من ذلك أن يكون له حق أن يجرّدهم من ممالكهم أو من حياتهم إذا حكم بأنهم هراطقة أو بأي حجة أخرى.', refs: ['1Tim.2.1-2', '1Pet.2.17', 'Rom.13.6-7', 'Rom.13.5', 'Titus.3.1', '1Pet.2.13-14', '1Pet.2.16', 'Rom.13.1', '1Kgs.2.35', 'Acts.25.9-11', '2Pet.2.1', '2Pet.2.10-11', 'Jude.1.8-11', '2Thess.2.4', 'Rev.13.15-17'] }
  ] },
  { n: 24, ar: 'الزواج والطلاق', en: 'Of Marriage and Divorce', id: 'marriage', secs: [
    { t: 'الزواج يكون بين رجل واحد وامرأة واحدة. فلا يجوز لرجل أن يكون له أكثر من زوجة واحدة، ولا لامرأة أكثر من زوج واحد في الوقت نفسه.', refs: ['Gen.2.24', 'Matt.19.5-6', 'Prov.2.17'] },
    { t: 'رُتب الزواج للمعونة المتبادلة بين الزوج والزوجة، ولزيادة الجنس البشري بنسل شرعي، والكنيسة بنسل مقدس، ولمنع النجاسة.', refs: ['Gen.2.18', 'Mal.2.15', '1Cor.7.2', '1Cor.7.9'] },
    { t: 'يجوز لكل أنواع الناس القادرين على إعطاء موافقتهم بحكمة أن يتزوجوا. لكن واجب المسيحيين أن يتزوجوا في الرب فقط. فالذين يعترفون بالدين الحق المُصلح لا يجوز أن يتزوجوا بغير المؤمنين أو بالبابويين أو بغيرهم من عبدة الأوثان. ولا يجوز للأتقياء أن يرتبطوا بنير غير متكافئ بالزواج من أشخاص أشرار معروفين بسيرتهم أو يتمسكون بهرطقات مهلكة.', refs: ['Heb.13.4', '1Tim.4.3', '1Cor.7.36-38', 'Gen.24.57-58', '1Cor.7.39', 'Gen.34.14', 'Exod.34.16', 'Deut.7.3-4', '1Kgs.11.4', 'Neh.13.25-27', 'Mal.2.11-12', '2Cor.6.14'] },
    { t: 'لا يُعقد الزواج ضمن درجات القرابة الدموية أو بالمصاهرة التي تحرّمها الكلمة، ولا يمكن أن تُجعل هذه الزيجات المحرمة شرعية بأي قانون بشري أو موافقة الطرفين حتى يعيشا معاً كزوج وزوجة. ولا يجوز للرجل أن يتزوج من أقارب زوجته من هو أقرب إليه بالدم مما يجوز له من أقاربه هو، ولا للمرأة من أقارب زوجها من هو أقرب مما يجوز لها من أقاربها.', refs: ['Lev.18.1-30', '1Cor.5.1', 'Amos.2.7', 'Mark.6.18', 'Lev.18.24-28'] },
    { t: 'الزنى أو الفسق المرتكب بعد الخطوبة، إذا اكتُشف قبل الزواج، يعطي الطرف البريء حقاً عادلاً في فسخ الخطوبة. وفي حالة الزنى بعد الزواج، يجوز للطرف البريء أن يطلب الطلاق، وبعد الطلاق يتزوج بآخر، كأن الطرف المذنب قد مات.', refs: ['Matt.1.18-20', 'Matt.5.31-32', 'Matt.19.9', 'Rom.7.2-3'] },
    { t: 'مع أن فساد الإنسان يميل إلى البحث عن حجج لفصل من جمعهم الله في الزواج، فلا شيء إلا الزنى، أو الهجر المتعمد الذي لا تستطيع الكنيسة ولا الحاكم المدني علاجه بأي حال، سبب كافٍ لحل رباط الزواج. وفي ذلك يجب أن تُتبع إجراءات علنية منظمة، ولا يُترك الأشخاص المعنيون لإرادتهم وتقديرهم في قضيتهم الخاصة.', refs: ['Matt.19.8-9', '1Cor.7.15', 'Matt.19.6', 'Deut.24.1-4'] }
  ] },
  { n: 25, ar: 'الكنيسة', en: 'Of the Church', id: 'church', secs: [
    { t: 'الكنيسة الجامعة أو العامة غير المنظورة تتكون من العدد الكامل للمختارين الذين جُمعوا أو يُجمعون أو سيُجمعون في واحد تحت المسيح رأسها. وهي العروس والجسد وملء الذي يملأ الكل في الكل.', refs: ['Eph.1.10', 'Eph.1.22-23', 'Eph.5.23', 'Eph.5.27', 'Eph.5.32', 'Col.1.18'] },
    { t: 'الكنيسة المنظورة، وهي أيضاً جامعة أو عامة تحت الإنجيل، غير محصورة في أمة واحدة كما كانت تحت الناموس، تتكون من كل الذين في العالم كله يعترفون بالدين الحق، مع أولادهم. وهي ملكوت الرب يسوع المسيح، وبيت الله وعائلته، وخارجها لا توجد إمكانية عادية للخلاص.', refs: ['1Cor.1.2', '1Cor.12.12-13', 'Ps.2.8', 'Rev.7.9', 'Rom.15.9-12', '1Cor.7.14', 'Acts.2.39', 'Ezek.16.20-21', 'Rom.11.16', 'Gen.3.15', 'Gen.17.7', 'Matt.13.47', 'Isa.9.7', 'Eph.2.19', 'Eph.3.15', 'Acts.2.47'] },
    { t: 'لهذه الكنيسة الجامعة المنظورة أعطى المسيح الخدمة والأقوال والفرائض الإلهية، لجمع القديسين وتكميلهم في هذه الحياة إلى نهاية العالم. وهو بحضوره وروحه، حسب وعده، يجعلها فعالة لذلك.', refs: ['1Cor.12.28', 'Eph.4.11-13', 'Matt.28.19-20', 'Isa.59.21'] },
    { t: 'هذه الكنيسة الجامعة كانت أحياناً أكثر ظهوراً وأحياناً أقل. والكنائس المحلية، وهي أعضاء فيها، أنقى أو أقل نقاوة بحسب ما يُعلَّم ويُقبل فيها من تعليم الإنجيل، وما تُمارس به الفرائض، وما تُؤدى به العبادة العامة.', refs: ['Rom.11.3-4', 'Rev.12.6', 'Rev.12.14', 'Rev.2.1-29', 'Rev.3.1-22', '1Cor.5.6-7'] },
    { t: 'أنقى الكنائس تحت السماء معرضة للخلط والضلال. وبعضها انحط حتى لم يعد كنائس للمسيح بل مجامع للشيطان. ومع ذلك ستبقى دائماً على الأرض كنيسة تعبد الله حسب مشيئته.', refs: ['1Cor.13.12', 'Rev.2.1-29', 'Rev.3.1-22', 'Matt.13.24-30', 'Matt.13.47', 'Rev.18.2', 'Rom.11.18-22', 'Matt.16.18', 'Ps.72.17', 'Ps.102.28', 'Matt.28.19-20'] },
    { t: 'لا رأس للكنيسة غير الرب يسوع المسيح. ولا يمكن أن يكون بابا روما رأسها بأي معنى، بل هو ذلك الضد للمسيح، إنسان الخطية وابن الهلاك، الذي يرفع نفسه في الكنيسة ضد المسيح وكل ما يُدعى إلهاً.', refs: ['Col.1.18', 'Eph.1.22', 'Matt.23.8-10', '2Thess.2.3-4', '2Thess.2.8-9', 'Rev.13.6'] }
  ] },
  { n: 26, ar: 'شركة القديسين', en: 'Of the Communion of Saints', id: 'communion', secs: [
    { t: 'كل القديسين المتحدين بيسوع المسيح رأسهم بروحه وبالإيمان، لهم شركة معه في نعمه وآلامه وموته وقيامته ومجده. وإذ هم متحدون بعضهم ببعض في المحبة، لهم شركة في عطايا بعضهم ونعمهم، وعليهم أن يقوموا بالواجبات العامة والخاصة التي تؤدي إلى خيرهم المتبادل، في الإنسان الباطن والخارج.', refs: ['1John.1.3', 'Eph.3.16-19', 'John.1.16', 'Eph.2.5-6', 'Phil.3.10', 'Rom.6.5-6', '2Tim.2.12', 'Eph.4.15-16', '1Cor.12.7', '1Cor.3.21-23', 'Col.2.19', '1Thess.5.11', '1Thess.5.14', 'Rom.1.11-12', 'Rom.1.14', '1John.3.16-18', 'Gal.6.10'] },
    { t: 'القديسون باعترافهم ملزمون أن يحفظوا شركة مقدسة وتواصلاً في عبادة الله، وفي القيام بالخدمات الروحية الأخرى التي تبنيهم بعضاً بعضاً، وكذلك في سد احتياجات بعضهم المادية حسب قدراتهم واحتياجاتهم. وهذه الشركة، حسب ما يتيحه الله، تمتد إلى كل من يدعون اسم الرب يسوع في كل مكان.', refs: ['Heb.10.24-25', 'Acts.2.42', 'Acts.2.46', 'Isa.2.3', '1Cor.11.20', 'Acts.2.44-45', '1John.3.17', '2Cor.8.1-24', '2Cor.9.1-15', 'Acts.11.29-30'] },
    { t: 'هذه الشركة التي للقديسين مع المسيح لا تجعلهم بأي حال شركاء في جوهر لاهوته، ولا مساوين للمسيح من أي وجه. والقول بأي من هذين كفر. ولا شركتهم كقديسين بعضهم مع بعض تلغي أو تمس حق كل إنسان في ملكيته وممتلكاته.', refs: ['Col.1.18-19', '1Cor.8.6', 'Isa.42.8', '1Tim.6.15-16', 'Ps.45.7', 'Heb.1.8-9', 'Exod.20.15', 'Eph.4.28', 'Acts.5.4'] }
  ] },
  { n: 27, ar: 'الأسرار المقدسة', en: 'Of the Sacraments', id: 'sacraments', secs: [
    { t: 'الأسرار علامات وأختام مقدسة لعهد النعمة، رتبها الله مباشرة، لتمثّل المسيح وفوائده، وتثبّت اهتمامنا به، وتضع فرقاً ظاهراً بين الذين ينتمون إلى الكنيسة وبقية العالم، وتلزمنا رسمياً بخدمة الله في المسيح حسب كلمته.', refs: ['Rom.4.11', 'Gen.17.7', 'Gen.17.10', 'Matt.28.19', '1Cor.11.23', '1Cor.10.16', '1Cor.11.25-26', 'Gal.3.27', 'Gal.3.17', 'Rom.15.8', 'Exod.12.48', 'Gen.34.14', '1Cor.10.21', 'Rom.6.3-4', '1Cor.10.16'] },
    { t: 'في كل سر علاقة روحية، أو اتحاد سرّي، بين العلامة والشيء المرموز إليه. ومن هنا يحدث أن تُنسب أسماء أحدهما وآثاره إلى الآخر.', refs: ['Gen.17.10', 'Matt.26.27-28', 'Titus.3.5'] },
    { t: 'النعمة المقدمة في الأسرار أو بها، حين تُمارس كما يجب، لا تُعطى بقوة فيها، ولا تعتمد فاعلية السر على تقوى أو نية من يمارسه، بل على عمل الروح، وعلى كلمة التأسيس التي تحوي، مع أمر استخدامه، وعداً بفائدة للمستحقين.', refs: ['Rom.2.28-29', '1Pet.3.21', 'Matt.3.11', '1Cor.12.13', 'Matt.26.27-28', 'Matt.28.19-20'] },
    { t: 'رتب المسيح ربنا في الإنجيل سرين فقط، هما المعمودية والعشاء الرباني. ولا يجوز لأحد أن يمارس أياً منهما إلا خادم الكلمة المرسوم شرعياً.', refs: ['Matt.28.19', '1Cor.11.20', '1Cor.11.23', '1Cor.4.1', 'Heb.5.4'] },
    { t: 'أسرار العهد القديم، من جهة الأمور الروحية التي رمزت إليها وقدمتها، كانت في جوهرها مثل أسرار العهد الجديد.', refs: ['1Cor.10.1-4'] }
  ] },
  { n: 28, ar: 'المعمودية', en: 'Of Baptism', id: 'baptism', secs: [
    { t: 'المعمودية سر من أسرار العهد الجديد رتبه يسوع المسيح، ليس فقط للإدخال الرسمي للمعمَّد إلى الكنيسة المنظورة، بل ليكون له أيضاً علامة وختماً لعهد النعمة، ولتطعيمه في المسيح، وللولادة الجديدة، ولغفران الخطايا، ولتسليم نفسه لله بيسوع المسيح ليسلك في جدة الحياة. وهذا السر يجب أن يستمر في كنيسته بأمر المسيح نفسه إلى نهاية العالم.', refs: ['Matt.28.19', '1Cor.12.13', 'Rom.4.11', 'Col.2.11-12', 'Gal.3.27', 'Rom.6.5', 'Titus.3.5', 'Mark.1.4', 'Rom.6.3-4', 'Matt.28.19-20'] },
    { t: 'العنصر الخارجي المستخدم في هذا السر هو الماء، الذي يُعمَّد به الشخص باسم الآب والابن والروح القدس، على يد خادم للإنجيل مدعو شرعياً لذلك.', refs: ['Matt.3.11', 'John.1.33', 'Matt.28.19-20'] },
    { t: 'التغطيس في الماء ليس ضرورياً، بل تُمارس المعمودية بشكل صحيح بسكب الماء أو رشه على الشخص.', refs: ['Heb.9.10', 'Heb.9.19-22', 'Acts.2.41', 'Acts.16.33', 'Mark.7.4'] },
    { t: 'ليس الذين يعترفون فعلياً بالإيمان بالمسيح والطاعة له فقط هم الذين يُعمَّدون، بل أيضاً أطفال أحد الوالدين المؤمنين أو كليهما.', refs: ['Mark.16.15-16', 'Acts.8.37-38', 'Gen.17.7', 'Gen.17.9-10', 'Gal.3.9', 'Gal.3.14', 'Col.2.11-12', 'Acts.2.38-39', 'Rom.4.11-12', '1Cor.7.14', 'Matt.28.19', 'Mark.10.13-16', 'Luke.18.15'] },
    { t: 'مع أن احتقار هذه الفريضة أو إهمالها خطية عظيمة، فإن النعمة والخلاص غير مرتبطين بها ارتباطاً لا ينفصل، بحيث لا يمكن لإنسان أن يتجدد أو يخلص بدونها، أو أن كل المعمَّدين قد تجددوا بلا شك.', refs: ['Luke.7.30', 'Exod.4.24-26', 'Rom.4.11', 'Acts.10.2', 'Acts.10.4', 'Acts.10.22', 'Acts.10.31', 'Acts.10.45', 'Acts.10.47', 'Acts.8.13', 'Acts.8.23'] },
    { t: 'فاعلية المعمودية ليست مرتبطة باللحظة التي تُمارس فيها. ومع ذلك، بالاستخدام الصحيح لهذه الفريضة، النعمة الموعود بها لا تُقدم فقط، بل تُعطى فعلاً بالروح القدس لكل من ينتمون إليها، كباراً أو أطفالاً، حسب مشورة مشيئة الله في وقته المعيّن.', refs: ['John.3.5', 'John.3.8', 'Gal.3.27', 'Titus.3.5', 'Eph.5.25-26', 'Acts.2.38', 'Acts.2.41'] },
    { t: 'سر المعمودية يُمارس مرة واحدة فقط لأي شخص.', refs: ['Titus.3.5'] }
  ] },
  { n: 29, ar: 'العشاء الرباني', en: "Of the Lord's Supper", id: 'lords-supper', secs: [
    { t: 'ربنا يسوع، في الليلة التي أُسلم فيها، رتب سر جسده ودمه، المسمى العشاء الرباني، ليُحفظ في كنيسته إلى نهاية العالم: لذكرى دائمة لذبيحة نفسه في موته، ولختم كل فوائدها للمؤمنين الحقيقيين، ولغذائهم الروحي ونموهم فيه، ولالتزامهم أكثر بكل الواجبات التي عليهم له، وليكون رباطاً وعربوناً لشركتهم معه ومع بعضهم كأعضاء في جسده السري.', refs: ['1Cor.11.23-26', '1Cor.10.16-17', '1Cor.10.21', '1Cor.12.13'] },
    { t: 'في هذا السر لا يُقدَّم المسيح لأبيه، ولا تُعمل أي ذبيحة حقيقية على الإطلاق لغفران خطايا الأحياء أو الأموات، بل هو فقط تذكار لتقديم المسيح نفسه، بنفسه، على الصليب، مرة واحدة للجميع، وتقدمة روحية لكل تسبيح ممكن لله لأجل ذلك. لذلك فذبيحة القداس البابوية، كما يسمونها، تسيء جداً إلى ذبيحة المسيح الواحدة، الكفارة الوحيدة لكل خطايا المختارين.', refs: ['Heb.9.22', 'Heb.9.25-26', 'Heb.9.28', '1Cor.11.24-26', 'Matt.26.26-27', 'Heb.7.23-24', 'Heb.7.27', 'Heb.10.11-12', 'Heb.10.14', 'Heb.10.18'] },
    { t: 'عيّن الرب يسوع خدامه في هذه الفريضة أن يعلنوا كلمة التأسيس للشعب، ويصلّوا ويباركوا عنصري الخبز والخمر، فيفرزوهما عن الاستعمال العادي للاستعمال المقدس، ويأخذوا الخبز ويكسروه، ويأخذوا الكأس، ويعطوا كليهما للمتناولين، ويتناولوا هم أيضاً، لكن لا يعطوها لأحد غير حاضر في الجماعة.', refs: ['Matt.26.26-28', 'Mark.14.22-24', 'Luke.22.19-20', '1Cor.11.23-26', 'Acts.20.7', '1Cor.11.20'] },
    { t: 'القداسات الخاصة، أو تناول هذا السر من كاهن أو غيره منفرداً، وكذلك منع الكأس عن الشعب، وعبادة العناصر، ورفعها أو حملها في موكب للعبادة، وحفظها لأي استعمال ديني مزعوم، كلها تخالف طبيعة هذا السر وتأسيس المسيح.', refs: ['1Cor.10.6', 'Mark.14.23', '1Cor.11.25-29', 'Matt.15.9'] },
    { t: 'العناصر الخارجية في هذا السر، المفرزة كما يجب للاستعمال الذي رتبه المسيح، لها علاقة به بحيث تُسمى أحياناً، حقاً لكن سرياً فقط، بأسماء ما تمثّله، أي جسد المسيح ودمه. ومع ذلك تبقى في جوهرها وطبيعتها خبزاً وخمراً فقط كما كانت قبلاً.', refs: ['Matt.26.26-28', '1Cor.11.26-28', 'Matt.26.29'] },
    { t: 'التعليم الذي يقول بتحول جوهر الخبز والخمر إلى جوهر جسد المسيح ودمه، المسمى عادة الاستحالة، بتكريس الكاهن أو بأي طريقة أخرى، ضد الكتاب وضد الحس العام والعقل أيضاً، ويقلب طبيعة السر، وقد كان وما زال سبباً لخرافات متعددة، بل لعبادة أوثان فاضحة.', refs: ['Acts.3.21', '1Cor.11.24-26', 'Luke.24.6', 'Luke.24.39'] },
    { t: 'المتناولون المستحقون، إذ يتناولون العناصر المنظورة خارجياً في هذا السر، يتناولون أيضاً داخلياً بالإيمان، حقاً وفعلاً، لكن لا جسدياً ولا مادياً بل روحياً، المسيح المصلوب وكل فوائد موته، ويتغذون به. وجسد المسيح ودمه ليسا حاضرين جسدياً أو مادياً في الخبز والخمر أو معهما أو تحتهما، لكنهما حاضران فعلاً وروحياً لإيمان المؤمنين في هذه الفريضة، كما أن العناصر نفسها حاضرة لحواسهم الخارجية.', refs: ['1Cor.11.28', '1Cor.10.16'] },
    { t: 'مع أن الجهلاء والأشرار يتناولون العناصر الخارجية في هذا السر، فإنهم لا ينالون ما ترمز إليه، بل بتقدمهم غير المستحق يصيرون مجرمين في جسد الرب ودمه لدينونتهم. لذلك فكل الجهلاء والأشرار، كما أنهم غير أهل للتمتع بالشركة معه، كذلك غير مستحقين لمائدة الرب، ولا يمكنهم وهم كذلك أن يشتركوا في هذه الأسرار المقدسة دون خطية عظيمة ضد المسيح، ولا أن يُسمح لهم بذلك.', refs: ['1Cor.11.27-29', '2Cor.6.14-16', '1Cor.5.6-7', '1Cor.5.13', '2Thess.3.6', '2Thess.3.14-15', 'Matt.7.6'] }
  ] },
  { n: 30, ar: 'التأديبات الكنسية', en: 'Of Church Censures', id: 'discipline', secs: [
    { t: 'الرب يسوع، كملك ورأس لكنيسته، عيّن فيها حكماً بأيدي خدام الكنيسة، متميزاً عن الحاكم المدني.', refs: ['Isa.9.6-7', '1Tim.5.17', '1Thess.5.12', 'Acts.20.17-18', 'Heb.13.7', 'Heb.13.17', 'Heb.13.24', '1Cor.12.28', 'Matt.28.18-20'] },
    { t: 'لهؤلاء الخدام سُلّمت مفاتيح ملكوت السماوات، فلهم سلطان أن يمسكوا الخطايا ويغفروها، وأن يغلقوا ذلك الملكوت في وجه غير التائبين بالكلمة والتأديبات، وأن يفتحوه للخطاة التائبين بخدمة الإنجيل وبالحِل من التأديبات حسب ما تتطلبه الحالة.', refs: ['Matt.16.19', 'Matt.18.17-18', 'John.20.21-23', '2Cor.2.6-8'] },
    { t: 'التأديبات الكنسية ضرورية لاسترداد الإخوة المخطئين وربحهم، ولردع الآخرين عن خطايا مماثلة، ولتنقية الخميرة التي قد تخمّر العجين كله، وللدفاع عن كرامة المسيح وعن الاعتراف المقدس بالإنجيل، ولمنع غضب الله الذي قد يحل بالكنيسة بحق إذا سمحت بأن يُدنّس عهده وختومه من مخالفين معروفين وعنيدين.', refs: ['1Cor.5.1-13', '1Tim.5.20', 'Matt.7.6', '1Tim.1.20', '1Cor.11.27-34', 'Jude.1.23'] },
    { t: 'لتحقيق هذه الغايات، على خدام الكنيسة أن يتدرجوا بالإنذار، ثم المنع من سر العشاء الرباني لبعض الوقت، ثم بالقطع من الكنيسة، حسب طبيعة الجريمة وذنب الشخص.', refs: ['1Thess.5.12', '2Thess.3.6', '2Thess.3.14-15', '1Cor.5.4-5', '1Cor.5.13', 'Matt.18.17', 'Titus.3.10'] }
  ] },
  { n: 31, ar: 'المجامع والمجالس', en: 'Of Synods and Councils', id: 'synods', secs: [
    { t: 'لأجل حكم أفضل للكنيسة وبنيان أكبر لها، يجب أن تكون هناك اجتماعات كالتي تُسمى عادة المجامع أو المجالس.', refs: ['Acts.15.2', 'Acts.15.4', 'Acts.15.6'] },
    { t: 'كما يجوز للحكام المدنيين أن يدعوا إلى مجمع من الخدام وغيرهم من المؤهلين للتشاور معهم في أمور الدين، كذلك إذا كان الحكام أعداء علنيين للكنيسة، يجوز لخدام المسيح، من تلقاء أنفسهم بحكم وظيفتهم، أو مع غيرهم من المؤهلين بتفويض من كنائسهم، أن يجتمعوا في مثل هذه المجامع. (والمراجعة الأمريكية سنة 1788 أعادت صياغة هذا الفصل، فحذفت حق الحاكم في الدعوة إلى المجامع، وجعلت ترتيبها لرعاة الكنائس وقادتها بحكم وظيفتهم.)', refs: ['Isa.49.23', '1Tim.2.1-2', '2Chr.19.8-11', '2Chr.29.1-36', '2Chr.30.1-27', 'Matt.2.4-5', 'Prov.11.14', 'Acts.15.2', 'Acts.15.4', 'Acts.15.22-23', 'Acts.15.25'] },
    { t: 'يحق للمجامع والمجالس، بطريق الخدمة، أن تحسم الخلافات في أمور الإيمان وقضايا الضمير، وأن تضع قواعد وتوجيهات لترتيب أفضل للعبادة العامة وحكم الكنيسة، وأن تقبل الشكاوى في حالات سوء الإدارة وتفصل فيها بسلطة. وقراراتها وأحكامها، إذا اتفقت مع كلمة الله، تُقبل بتوقير وخضوع، ليس فقط لاتفاقها مع الكلمة، بل أيضاً للسلطة التي صدرت عنها، كفريضة من الله رتبها في كلمته.', refs: ['Acts.15.15', 'Acts.15.19', 'Acts.15.24', 'Acts.15.27-31', 'Acts.16.4', 'Matt.18.17-20'] },
    { t: 'كل المجامع والمجالس منذ أيام الرسل، عامة كانت أو محلية، قد تخطئ، وكثير منها أخطأ. لذلك لا تُجعل قاعدة للإيمان أو الحياة، بل تُستخدم كمعونة في كليهما.', refs: ['Eph.2.20', 'Acts.17.11', '1Cor.2.5', '2Cor.1.24'] },
    { t: 'المجامع والمجالس لا تعالج ولا تحسم إلا ما هو كنسي، ولا تتدخل في الشؤون المدنية التي تخص الدولة، إلا بالالتماس المتواضع في حالات استثنائية، أو بالنصح لإراحة الضمير إذا طلب منها الحاكم المدني ذلك.', refs: ['Luke.12.13-14', 'John.18.36'] }
  ] },
  { n: 32, ar: 'حالة البشر بعد الموت وقيامة الأموات', en: 'Of the State of Men after Death, and of the Resurrection of the Dead', id: 'resurrection', secs: [
    { t: 'أجساد البشر بعد الموت تعود إلى التراب وترى فساداً. لكن نفوسهم، التي لا تموت ولا تنام، إذ لها كيان خالد، تعود مباشرة إلى الله الذي أعطاها. نفوس الأبرار، إذ تُكمَّل في القداسة، تُقبل في أعلى السماوات، حيث ترى وجه الله في النور والمجد، منتظرة الفداء الكامل لأجسادها. ونفوس الأشرار تُطرح في الجحيم، حيث تبقى في العذاب والظلمة الكاملة، محفوظة لدينونة اليوم العظيم. وغير هذين المكانين للنفوس المنفصلة عن أجسادها لا يعترف الكتاب بأي مكان.', refs: ['Gen.3.19', 'Acts.13.36', 'Luke.23.43', 'Eccl.12.7', 'Heb.12.23', '2Cor.5.1', '2Cor.5.6', '2Cor.5.8', 'Phil.1.23', 'Acts.3.21', 'Eph.4.10', 'Rom.8.23', 'Luke.16.23-24', 'Acts.1.25', 'Jude.1.6-7', '1Pet.3.19'] },
    { t: 'الذين يوجدون أحياء في اليوم الأخير لن يموتوا بل يتغيرون. وكل الأموات يُقامون بنفس الأجساد ذاتها، لا بغيرها، وإن كانت بصفات مختلفة، وتتحد ثانية بنفوسها إلى الأبد.', refs: ['1Thess.4.17', '1Cor.15.51-52', 'Job.19.26-27', '1Cor.15.42-44'] },
    { t: 'أجساد الأشرار تُقام بقوة المسيح إلى العار. وأجساد الأبرار، بروحه، إلى الكرامة، وتصير مشابهة لجسد مجده.', refs: ['Acts.24.15', 'John.5.28-29', '1Cor.15.43', 'Phil.3.21'] }
  ] },
  { n: 33, ar: 'الدينونة الأخيرة', en: 'Of the Last Judgment', id: 'judgment', secs: [
    { t: 'عيّن الله يوماً سيدين فيه العالم بالبر، بيسوع المسيح، الذي أعطاه الآب كل سلطان ودينونة. وفي ذلك اليوم لا يُدان الملائكة الساقطون فقط، بل كل الأشخاص الذين عاشوا على الأرض، يقفون أمام كرسي المسيح ليقدموا حساباً عن أفكارهم وأقوالهم وأفعالهم، ويأخذوا حسب ما صنعوا بالجسد، خيراً كان أم شراً.', refs: ['Acts.17.31', 'John.5.22', 'John.5.27', '1Cor.6.3', 'Jude.1.6', '2Pet.2.4', '2Cor.5.10', 'Eccl.12.14', 'Rom.2.16', 'Rom.14.10', 'Rom.14.12', 'Matt.12.36-37'] },
    { t: 'غاية الله في تعيين هذا اليوم هي إظهار مجد رحمته في الخلاص الأبدي للمختارين، ومجد عدله في هلاك الأشرار المصرّين على العصيان. فحينئذ يدخل الأبرار إلى الحياة الأبدية، وينالون ملء الفرح والانتعاش الآتي من حضرة الرب. أما الأشرار، الذين لا يعرفون الله ولا يطيعون إنجيل يسوع المسيح، فيُطرحون في العذابات الأبدية، ويُعاقبون بهلاك أبدي من وجه الرب ومن مجد قوته.', refs: ['Matt.25.31-46', 'Rom.2.5-6', 'Rom.9.22-23', 'Matt.25.21', 'Acts.3.19', '2Thess.1.7-10'] },
    { t: 'كما أراد المسيح أن نقتنع يقيناً بأن هناك يوم دينونة، ليردع الجميع عن الخطية، ولتعزية أعظم للأتقياء في ضيقاتهم، كذلك يريد أن يبقى ذلك اليوم مجهولاً للناس، لكي يتخلصوا من كل اتكال جسدي، ويكونوا ساهرين دائماً لأنهم لا يعرفون في أي ساعة يأتي الرب، ويكونوا مستعدين دائماً أن يقولوا: تعال أيها الرب يسوع، تعال سريعاً. آمين.', refs: ['2Pet.3.11', '2Pet.3.14', '2Cor.5.10-11', '2Thess.1.5-7', 'Luke.21.27-28', 'Rom.8.23-25', 'Matt.24.36', 'Matt.24.42-44', 'Mark.13.35-37', 'Luke.12.35-36', 'Rev.22.20'] }
  ] }
];
